globalThis.TF_PHRASE_DATA=globalThis.TF_PHRASE_DATA||{};globalThis.TF_PHRASE_DATA["proverbs"]={"schemaVersion":1,"collection":"proverbs","title":"Tục ngữ tiếng Anh","count":400,"items":[{"id":"prv-0001","text":"Actions speak louder than words.","vi":"Hành động có sức thuyết phục hơn lời nói.","ex":"She volunteered every weekend; actions speak louder than words.","exVi":"Cô ấy tình nguyện mỗi cuối tuần; hành động có sức thuyết phục hơn lời nói.","src":null,"level":"general","topics":["Hành động","Giao tiếp"],"reg":"not-applicable","equiv":"Nói hay không bằng làm","ielts":1,"reviewed":false},{"id":"prv-0002","text":"Better late than never.","vi":"Muộn còn hơn không.","ex":"He has finally started exercising—better late than never.","exVi":"Cuối cùng anh ấy cũng bắt đầu tập thể dục—muộn còn hơn không.","src":null,"level":"general","topics":["Thời gian"],"reg":"not-applicable","equiv":"Muộn còn hơn không","ielts":1,"reviewed":false},{"id":"prv-0003","text":"Practice makes perfect.","vi":"Luyện tập thường xuyên giúp tiến bộ và thành thạo.","ex":"Keep speaking English; practice makes perfect.","exVi":"Hãy tiếp tục nói tiếng Anh; luyện tập sẽ giúp bạn thành thạo.","src":null,"level":"general","topics":["Học tập"],"reg":"not-applicable","equiv":"Có công mài sắt, có ngày nên kim","ielts":1,"reviewed":false},{"id":"prv-0004","text":"Where there is a will, there is a way.","vi":"Có chí thì nên.","ex":"They found a way to study despite their busy schedules. Where there is a will, there is a way.","exVi":"Họ tìm được cách học dù lịch trình bận rộn. Có chí thì nên.","src":null,"level":"general","topics":["Kiên trì"],"reg":"not-applicable","equiv":"Có chí thì nên","ielts":1,"reviewed":false},{"id":"prv-0005","text":"A picture is worth a thousand words.","vi":"Một hình ảnh có thể truyền tải rất nhiều điều.","ex":"The photograph explains the damage better than a long report; a picture is worth a thousand words.","exVi":"Bức ảnh giải thích thiệt hại rõ hơn một báo cáo dài; một hình ảnh có giá trị hơn ngàn lời nói.","src":null,"level":"general","topics":["Giao tiếp"],"reg":"not-applicable","equiv":"Trăm nghe không bằng một thấy","ielts":1,"reviewed":false},{"id":"prv-0006","text":"Do not judge a book by its cover.","vi":"Đừng đánh giá qua vẻ bề ngoài.","ex":"The quiet student had brilliant ideas, so do not judge a book by its cover.","exVi":"Bạn học sinh ít nói có những ý tưởng xuất sắc, vì thế đừng đánh giá qua vẻ ngoài.","src":null,"level":"general","topics":["Tư duy","Quan hệ"],"reg":"not-applicable","equiv":"Tốt gỗ hơn tốt nước sơn","ielts":1,"reviewed":false},{"id":"prv-0007","text":"Two heads are better than one.","vi":"Một người làm sao bằng hai người cùng nghĩ.","ex":"Let us solve this problem together; two heads are better than one.","exVi":"Hãy cùng giải quyết vấn đề này; hai người cùng nghĩ sẽ tốt hơn một.","src":null,"level":"general","topics":["Công việc","Hợp tác"],"reg":"not-applicable","equiv":"Một cây làm chẳng nên non, ba cây chụm lại nên hòn núi cao","ielts":1,"reviewed":false},{"id":"prv-0008","text":"Every cloud has a silver lining.","vi":"Trong khó khăn vẫn có điều tích cực.","ex":"Losing that job was difficult, but it led her to a better career. Every cloud has a silver lining.","exVi":"Mất công việc đó thật khó khăn, nhưng nó giúp cô tìm được sự nghiệp tốt hơn. Trong khó khăn vẫn có điều tích cực.","src":null,"level":"general","topics":["Cảm xúc","Kiên trì"],"reg":"not-applicable","equiv":"Trong cái rủi có cái may","ielts":1,"reviewed":false},{"id":"prv-0009","text":"When in Rome, do as the Romans do.","vi":"Nhập gia tùy tục.","ex":"I tried the local greeting because when in Rome, do as the Romans do.","exVi":"Tôi thử cách chào địa phương vì nhập gia thì nên tùy tục.","src":null,"level":"general","topics":["Du lịch","Văn hóa"],"reg":"not-applicable","equiv":"Nhập gia tùy tục","ielts":1,"reviewed":false},{"id":"prv-0010","text":"The early bird catches the worm.","vi":"Ai nhanh tay/chủ động thì có lợi thế.","ex":"She applied as soon as the position opened; the early bird catches the worm.","exVi":"Cô ấy nộp đơn ngay khi vị trí tuyển dụng mở; người chủ động sẽ có lợi thế.","src":null,"level":"general","topics":["Thời gian","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0011","text":"You cannot have your cake and eat it too.","vi":"Không thể vừa muốn giữ nguyên vừa muốn hưởng trọn lợi ích của thứ đó.","ex":"You must choose between saving time and checking every detail; you cannot have your cake and eat it too.","exVi":"Bạn phải chọn giữa tiết kiệm thời gian và kiểm tra mọi chi tiết; không thể có cả hai điều đó.","src":null,"level":"general","topics":["Lựa chọn"],"reg":"not-applicable","equiv":"Được cái này mất cái kia","ielts":1,"reviewed":false},{"id":"prv-0012","text":"All that glitters is not gold.","vi":"Không phải thứ gì trông hấp dẫn cũng có giá trị thật.","ex":"The offer looked impressive, but the hidden fees showed that all that glitters is not gold.","exVi":"Lời mời trông rất hấp dẫn, nhưng các khoản phí ẩn cho thấy không phải thứ gì lấp lánh cũng là vàng.","src":null,"level":"general","topics":["Tiền bạc","Tư duy"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0013","text":"A friend in need is a friend indeed.","vi":"Người ở bên giúp đỡ lúc khó khăn mới là bạn chân thành.","ex":"When I was ill, Minh brought me notes from class; a friend in need is a friend indeed.","exVi":"Khi tôi ốm, Minh mang ghi chép trên lớp đến; lúc khó khăn mới biết ai là bạn tốt.","src":null,"level":"general","topics":["Quan hệ"],"reg":"not-applicable","equiv":"Hoạn nạn mới biết chân tình","ielts":1,"reviewed":false},{"id":"prv-0014","text":"Birds of a feather flock together.","vi":"Những người giống nhau thường tìm đến nhau.","ex":"They both love volunteering, so birds of a feather flock together.","exVi":"Cả hai đều thích hoạt động tình nguyện nên những người cùng sở thích thường gắn bó.","src":null,"level":"general","topics":["Quan hệ"],"reg":"not-applicable","equiv":"Ngưu tầm ngưu, mã tầm mã","ielts":1,"reviewed":false},{"id":"prv-0015","text":"Do not put all your eggs in one basket.","vi":"Đừng đặt toàn bộ hy vọng vào một lựa chọn duy nhất.","ex":"Apply to several universities; do not put all your eggs in one basket.","exVi":"Hãy nộp hồ sơ vào vài trường; đừng đặt mọi hy vọng vào một lựa chọn.","src":null,"level":"general","topics":["Tiền bạc","Rủi ro"],"reg":"not-applicable","equiv":"Không bỏ trứng vào một giỏ","ielts":1,"reviewed":false},{"id":"prv-0016","text":"Rome was not built in a day.","vi":"Việc lớn cần thời gian và sự kiên trì.","ex":"Fluency takes years of practice—Rome was not built in a day.","exVi":"Nói lưu loát cần nhiều năm luyện tập; thành quả lớn không thể có trong một ngày.","src":null,"level":"general","topics":["Kiên trì","Thời gian"],"reg":"not-applicable","equiv":"Dục tốc bất đạt","ielts":1,"reviewed":false},{"id":"prv-0017","text":"Honesty is the best policy.","vi":"Trung thực là cách ứng xử tốt nhất.","ex":"She admitted the mistake because honesty is the best policy.","exVi":"Cô thừa nhận lỗi vì trung thực luôn là cách tốt nhất.","src":null,"level":"general","topics":["Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0018","text":"The grass is always greener on the other side.","vi":"Ta thường nghĩ hoàn cảnh của người khác tốt hơn của mình.","ex":"He envied his colleague’s job, but the grass is always greener on the other side.","exVi":"Anh ghen tị với công việc của đồng nghiệp, nhưng ta thường chỉ thấy mặt tốt của người khác.","src":null,"level":"general","topics":["Cảm xúc","Tư duy"],"reg":"not-applicable","equiv":"Đứng núi này trông núi nọ","ielts":1,"reviewed":false},{"id":"prv-0019","text":"Necessity is the mother of invention.","vi":"Nhu cầu thúc đẩy con người sáng tạo.","ex":"With no car, they built a simple cart; necessity is the mother of invention.","exVi":"Không có xe, họ tự làm một chiếc xe kéo đơn giản; nhu cầu thúc đẩy sáng kiến.","src":null,"level":"general","topics":["Công nghệ"],"reg":"not-applicable","equiv":"Cái khó ló cái khôn","ielts":1,"reviewed":false},{"id":"prv-0020","text":"No pain, no gain.","vi":"Muốn đạt kết quả phải chấp nhận nỗ lực.","ex":"Training is demanding, but no pain, no gain.","exVi":"Buổi tập rất vất vả, nhưng muốn tiến bộ phải nỗ lực.","src":null,"level":"general","topics":["Sức khỏe","Kiên trì"],"reg":"not-applicable","equiv":"Có làm thì mới có ăn","ielts":1,"reviewed":false},{"id":"prv-0021","text":"A watched pot never boils.","vi":"Càng sốt ruột chờ đợi, ta càng cảm thấy thời gian trôi chậm.","ex":"Stop checking the application page every minute; a watched pot never boils.","exVi":"Đừng kiểm tra trang hồ sơ mỗi phút; càng sốt ruột thì thời gian càng lâu trôi.","src":null,"level":"general","topics":["Thời gian","Kiên nhẫn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0022","text":"Many hands make light work.","vi":"Nhiều người cùng làm thì việc nặng hóa nhẹ.","ex":"The class cleaned the beach together; many hands make light work.","exVi":"Cả lớp cùng dọn bãi biển; nhiều người chung tay thì việc nặng hóa nhẹ.","src":null,"level":"general","topics":["Công việc","Hợp tác"],"reg":"not-applicable","equiv":"Một cây làm chẳng nên non","ielts":1,"reviewed":false},{"id":"prv-0023","text":"Look before you leap.","vi":"Hãy cân nhắc trước khi hành động.","ex":"Read the contract carefully—look before you leap.","exVi":"Hãy đọc kỹ hợp đồng trước khi ký; cần cân nhắc trước khi hành động.","src":null,"level":"general","topics":["Quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0024","text":"You reap what you sow.","vi":"Gieo nhân nào gặt quả ấy.","ex":"Her steady effort paid off; you reap what you sow.","exVi":"Nỗ lực đều đặn của cô đã được đền đáp; gieo nhân nào gặt quả ấy.","src":null,"level":"general","topics":["Hành động","Kết quả"],"reg":"not-applicable","equiv":"Gieo nhân nào gặt quả nấy","ielts":1,"reviewed":false},{"id":"prv-0025","text":"A stitch in time saves nine.","vi":"Xử lý sớm một vấn đề nhỏ có thể tránh được nhiều công sức về sau.","ex":"Mina fixed the loose button immediately; a stitch in time saves nine.","exVi":"Mina khâu lại chiếc cúc bị lỏng ngay; xử lý sớm sẽ đỡ vất vả về sau.","src":null,"level":"general","topics":["Thời gian","Sức khỏe"],"reg":"not-applicable","equiv":"Phòng bệnh hơn chữa bệnh","ielts":1,"reviewed":false},{"id":"prv-0026","text":"An apple a day keeps the doctor away.","vi":"Thói quen chăm sóc sức khỏe mỗi ngày giúp hạn chế bệnh tật.","ex":"My uncle says an apple a day keeps the doctor away, so he packs one daily.","exVi":"Chú tôi nói ăn táo mỗi ngày giúp khỏe mạnh, nên ngày nào chú cũng mang theo một quả.","src":null,"level":"general","topics":["Sức khỏe","Đồ ăn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0027","text":"Don't count your chickens before they hatch.","vi":"Đừng vội cho rằng kết quả đã chắc chắn khi việc còn chưa hoàn tất.","ex":"The offer is not signed, so don't count your chickens before they hatch.","exVi":"Lời đề nghị chưa được ký kết, nên đừng vội mừng khi mọi việc chưa ngã ngũ.","src":null,"level":"general","topics":["Lựa chọn","Rủi ro"],"reg":"not-applicable","equiv":"Đừng đếm cua trong lỗ","ielts":1,"reviewed":false},{"id":"prv-0028","text":"Don't bite the hand that feeds you.","vi":"Đừng đối xử tệ hoặc quay lưng với người đang giúp đỡ mình.","ex":"Don't bite the hand that feeds you, even when giving feedback.","exVi":"Đừng quay lưng với người đang giúp mình, kể cả khi góp ý cho họ.","src":null,"level":"general","topics":["Quan hệ","Giao tiếp"],"reg":"not-applicable","equiv":"Qua cầu rút ván","ielts":1,"reviewed":false},{"id":"prv-0029","text":"Too many cooks spoil the broth.","vi":"Quá nhiều người cùng can thiệp có thể khiến kết quả kém đi.","ex":"The committee rewrote one email ten times; too many cooks spoil the broth.","exVi":"Ban tổ chức sửa một email đến mười lần; quá nhiều người góp tay đôi khi làm hỏng việc.","src":null,"level":"general","topics":["Công việc","Hợp tác"],"reg":"not-applicable","equiv":"Lắm thầy thối ma","ielts":1,"reviewed":false},{"id":"prv-0030","text":"The pen is mightier than the sword.","vi":"Ngôn từ và ý tưởng có thể tạo ảnh hưởng mạnh hơn vũ lực.","ex":"The journalist believed the pen is mightier than the sword during wartime.","exVi":"Nhà báo tin rằng ngòi bút có thể mạnh hơn gươm giáo trong thời chiến.","src":null,"level":"general","topics":["Giao tiếp","Truyền thông"],"reg":"not-applicable","equiv":"Ngòi bút mạnh hơn gươm giáo","ielts":1,"reviewed":false},{"id":"prv-0031","text":"Don't make a mountain out of a molehill.","vi":"Đừng phóng đại một vấn đề nhỏ thành chuyện nghiêm trọng.","ex":"Don't make a mountain out of a molehill over a minor delay.","exVi":"Đừng chuyện bé xé ra to chỉ vì một chút chậm trễ.","src":null,"level":"general","topics":["Cảm xúc","Tư duy"],"reg":"not-applicable","equiv":"Chuyện bé xé ra to","ielts":1,"reviewed":false},{"id":"prv-0032","text":"Curiosity killed the cat.","vi":"Tò mò quá mức hoặc xen vào chuyện không liên quan có thể gây rắc rối.","ex":"Curiosity killed the cat, so Sam asked before opening the sealed parcel.","exVi":"Tò mò quá mức có thể gây rắc rối, nên Sam hỏi trước khi mở gói hàng niêm phong.","src":null,"level":"general","topics":["Tư duy","Đời sống"],"reg":"not-applicable","equiv":"Tò mò hại thân","ielts":1,"reviewed":false},{"id":"prv-0033","text":"The proof of the pudding is in the eating.","vi":"Chỉ có trải nghiệm thực tế mới cho thấy điều gì đó tốt hay không.","ex":"We cannot judge the recipe yet; the proof of the pudding is in the eating.","exVi":"Chúng ta chưa thể đánh giá công thức; phải thử mới biết nó có ngon không.","src":null,"level":"general","topics":["Đồ ăn","Trải nghiệm"],"reg":"not-applicable","equiv":"Có thử mới biết","ielts":1,"reviewed":false},{"id":"prv-0034","text":"You can't teach an old dog new tricks.","vi":"Thay đổi thói quen lâu năm của một người thường không dễ.","ex":"You can't teach an old dog new tricks, but you can offer patient practice.","exVi":"Thói quen cũ khó đổi, nhưng ta có thể kiên nhẫn luyện tập từng chút một.","src":null,"level":"general","topics":["Học tập","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0035","text":"A chain is only as strong as its weakest link.","vi":"Một tập thể hoặc hệ thống chỉ vững bằng mắt xích yếu nhất của nó.","ex":"The backup plan failed because a chain is only as strong as its weakest link.","exVi":"Kế hoạch dự phòng thất bại vì một hệ thống chỉ vững bằng mắt xích yếu nhất.","src":null,"level":"general","topics":["Công việc","Hợp tác"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0036","text":"A leopard cannot change its spots.","vi":"Tính cách hoặc bản chất đã ăn sâu thường khó thay đổi.","ex":"He repeated the same careless habit; a leopard cannot change its spots, she sighed.","exVi":"Anh ấy lại lặp thói quen bất cẩn; cô thở dài rằng bản tính khó đổi.","src":null,"level":"general","topics":["Tư duy","Quan hệ"],"reg":"not-applicable","equiv":"Giang sơn dễ đổi, bản tính khó dời","ielts":1,"reviewed":false},{"id":"prv-0037","text":"Never look a gift horse in the mouth.","vi":"Đừng soi xét hay chê bai món quà mình được tặng.","ex":"They offered me a desk; I would never look a gift horse in the mouth.","exVi":"Họ tặng tôi chiếc bàn; tôi sẽ không chê bai món quà ấy.","src":null,"level":"general","topics":["Quan hệ","Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0038","text":"Better safe than sorry.","vi":"Cẩn trọng trước thường tốt hơn phải hối tiếc vì đã chủ quan.","ex":"We checked the weather twice; better safe than sorry.","exVi":"Chúng tôi kiểm tra thời tiết hai lần; cẩn thận vẫn hơn phải tiếc nuối.","src":null,"level":"general","topics":["Rủi ro","Sức khỏe"],"reg":"not-applicable","equiv":"Cẩn tắc vô áy náy","ielts":1,"reviewed":false},{"id":"prv-0039","text":"Don't put off until tomorrow what you can do today.","vi":"Đừng trì hoãn đến ngày mai việc mình có thể hoàn thành hôm nay.","ex":"Don't put off until tomorrow what you can do today, my teacher reminded us.","exVi":"Cô giáo nhắc chúng tôi đừng để việc hôm nay sang ngày mai.","src":null,"level":"general","topics":["Thời gian","Học tập"],"reg":"not-applicable","equiv":"Việc hôm nay chớ để ngày mai","ielts":1,"reviewed":false},{"id":"prv-0040","text":"Easy come, easy go.","vi":"Thứ có được dễ dàng đôi khi cũng mất đi nhanh chóng.","ex":"He lost the prize money and shrugged; easy come, easy go.","exVi":"Anh ấy mất khoản tiền thưởng rồi nhún vai; thứ đến dễ thì đi cũng nhanh.","src":null,"level":"general","topics":["Tiền bạc","Đời sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0041","text":"Fortune favors the bold.","vi":"Người dám chủ động nắm lấy cơ hội thường có lợi thế.","ex":"She applied for the fellowship despite her nerves; fortune favors the bold.","exVi":"Dù lo lắng, cô vẫn nộp đơn xin học bổng; người mạnh dạn thường có lợi thế.","src":null,"level":"general","topics":["Cơ hội","Công việc"],"reg":"not-applicable","equiv":"Có gan làm giàu","ielts":1,"reviewed":false},{"id":"prv-0042","text":"Good things come to those who wait.","vi":"Kiên nhẫn có thể giúp ta đạt được kết quả tốt vào đúng lúc.","ex":"After months of careful practice, good things come to those who wait.","exVi":"Sau nhiều tháng luyện tập cẩn thận, sự kiên nhẫn cuối cùng cũng đem lại kết quả.","src":null,"level":"general","topics":["Kiên nhẫn","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0043","text":"Half a loaf is better than no bread.","vi":"Có được một phần vẫn tốt hơn là chẳng có gì.","ex":"The shop had one loaf left, but half a loaf is better than no bread.","exVi":"Cửa hàng chỉ còn một ổ bánh, nhưng có một phần vẫn hơn là không có gì.","src":null,"level":"general","topics":["Lựa chọn","Đồ ăn"],"reg":"not-applicable","equiv":"Có còn hơn không","ielts":1,"reviewed":false},{"id":"prv-0044","text":"If it ain't broke, don't fix it.","vi":"Nếu điều gì vẫn hoạt động tốt thì không cần sửa đổi vô cớ.","ex":"The old projector still works; if it ain't broke, don't fix it.","exVi":"Máy chiếu cũ vẫn chạy tốt; nếu chưa hỏng thì không cần sửa.","src":null,"level":"general","topics":["Công nghệ","Công việc"],"reg":"not-applicable","equiv":"Đang yên đang lành, đừng đụng vào","ielts":1,"reviewed":false},{"id":"prv-0045","text":"Laughter is the best medicine.","vi":"Niềm vui và tiếng cười có thể giúp con người cảm thấy khá hơn.","ex":"A shared joke eased the tense afternoon; laughter is the best medicine.","exVi":"Một câu chuyện vui làm dịu buổi chiều căng thẳng; tiếng cười giúp tinh thần nhẹ nhõm hơn.","src":null,"level":"general","topics":["Sức khỏe","Cảm xúc"],"reg":"not-applicable","equiv":"Một nụ cười bằng mười thang thuốc bổ","ielts":1,"reviewed":false},{"id":"prv-0046","text":"Let sleeping dogs lie.","vi":"Đừng khơi lại chuyện cũ có thể gây thêm rắc rối.","ex":"They decided to let sleeping dogs lie and avoid reopening the old argument.","exVi":"Họ quyết định không khơi lại chuyện cũ để tránh tranh cãi thêm.","src":null,"level":"general","topics":["Quan hệ","Quyết định"],"reg":"not-applicable","equiv":"Đừng khơi lại chuyện cũ","ielts":1,"reviewed":false},{"id":"prv-0047","text":"Money doesn't grow on trees.","vi":"Tiền bạc có giới hạn, vì vậy cần chi tiêu có cân nhắc.","ex":"We compared prices because money doesn't grow on trees.","exVi":"Chúng tôi so sánh giá vì tiền bạc không tự nhiên mà có.","src":null,"level":"general","topics":["Tiền bạc","Gia đình"],"reg":"not-applicable","equiv":"Tiền không mọc trên cây","ielts":1,"reviewed":false},{"id":"prv-0048","text":"Nothing ventured, nothing gained.","vi":"Nếu không dám thử điều mới thì khó có được thành quả.","ex":"He entered the design contest; nothing ventured, nothing gained.","exVi":"Anh ấy tham gia cuộc thi thiết kế; không thử thì khó có được thành quả.","src":null,"level":"general","topics":["Cơ hội","Học tập"],"reg":"not-applicable","equiv":"Có gan làm giàu","ielts":1,"reviewed":false},{"id":"prv-0049","text":"One good turn deserves another.","vi":"Khi nhận được sự giúp đỡ tử tế, ta nên đáp lại bằng việc tốt.","ex":"A neighbor watered our plants, so one good turn deserves another.","exVi":"Hàng xóm tưới cây giúp chúng tôi, nên chúng tôi cũng muốn đáp lại bằng việc tốt.","src":null,"level":"general","topics":["Quan hệ","Giá trị sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0050","text":"Out of sight, out of mind.","vi":"Điều ta ít nhìn thấy thường dần ít hiện diện trong suy nghĩ.","ex":"She keeps the library book beside her bag; out of sight, out of mind.","exVi":"Cô để sách thư viện cạnh túi; để khuất tầm mắt là dễ quên.","src":null,"level":"general","topics":["Thói quen","Đời sống"],"reg":"not-applicable","equiv":"Xa mặt cách lòng","ielts":1,"reviewed":false},{"id":"prv-0051","text":"There's no place like home.","vi":"Không nơi nào đem lại cảm giác thân thuộc và dễ chịu như nhà mình.","ex":"After a month abroad, I understood why there's no place like home.","exVi":"Sau một tháng ở nước ngoài, tôi hiểu vì sao không nơi nào thân thuộc như nhà.","src":null,"level":"general","topics":["Nhà cửa","Du lịch"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0052","text":"Time and tide wait for no one.","vi":"Thời gian và cơ hội không dừng lại để chờ bất kỳ ai.","ex":"We should start the garden today; time and tide wait for no one.","exVi":"Chúng ta nên bắt đầu khu vườn hôm nay; thời gian không chờ đợi ai.","src":null,"level":"general","topics":["Thời gian","Môi trường"],"reg":"not-applicable","equiv":"Thời gian không chờ đợi ai","ielts":1,"reviewed":false},{"id":"prv-0053","text":"Two wrongs don't make a right.","vi":"Đáp trả một việc sai bằng việc sai khác không khiến tình hình trở nên đúng đắn.","ex":"He apologized rather than retaliate; two wrongs don't make a right.","exVi":"Anh ấy xin lỗi thay vì trả đũa; sai lầm này không thể sửa bằng sai lầm khác.","src":null,"level":"general","topics":["Giá trị sống","Quan hệ"],"reg":"not-applicable","equiv":"Lấy oán trả oán chỉ làm oán chồng thêm","ielts":1,"reviewed":false},{"id":"prv-0054","text":"A bad workman blames his tools.","vi":"Người làm việc kém thường đổ lỗi cho dụng cụ thay vì nhận trách nhiệm.","ex":"He blamed the dull scissors, but a bad workman blames his tools.","exVi":"Anh ấy đổ lỗi cho chiếc kéo cùn, nhưng người làm kém thường đổ lỗi cho dụng cụ.","src":null,"level":"general","topics":["Công việc","Trách nhiệm"],"reg":"not-applicable","equiv":"Thợ vụng đổ lỗi cho đồ nghề","ielts":1,"reviewed":false},{"id":"prv-0055","text":"Absence makes the heart grow fonder.","vi":"Xa cách đôi khi khiến tình cảm và sự nhớ nhung thêm sâu đậm.","ex":"They missed each other during the exchange; absence makes the heart grow fonder.","exVi":"Họ nhớ nhau trong thời gian trao đổi; xa cách đôi khi làm tình cảm thêm sâu đậm.","src":null,"level":"general","topics":["Quan hệ","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0056","text":"All's well that ends well.","vi":"Kết quả tốt đẹp khiến những khó khăn trước đó trở nên dễ chấp nhận hơn.","ex":"The trip had delays, but the group got home safely; all's well that ends well.","exVi":"Chuyến đi bị trễ, nhưng cả nhóm về nhà an toàn; kết quả tốt đẹp là điều đáng mừng.","src":null,"level":"general","topics":["Trải nghiệm","Du lịch"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0057","text":"Beauty is in the eye of the beholder.","vi":"Cảm nhận về cái đẹp khác nhau tùy mỗi người.","ex":"They chose different posters because beauty is in the eye of the beholder.","exVi":"Họ chọn những tấm áp phích khác nhau vì mỗi người có cảm nhận riêng về cái đẹp.","src":null,"level":"general","topics":["Nghệ thuật","Tư duy"],"reg":"not-applicable","equiv":"Mỗi người một gu","ielts":1,"reviewed":false},{"id":"prv-0058","text":"Blood is thicker than water.","vi":"Tình thân gia đình thường được xem là bền chặt hơn những mối quan hệ khác.","ex":"They disagree often, yet she believes blood is thicker than water.","exVi":"Họ thường bất đồng, nhưng cô vẫn tin tình thân gia đình rất bền chặt.","src":null,"level":"general","topics":["Gia đình","Quan hệ"],"reg":"not-applicable","equiv":"Một giọt máu đào hơn ao nước lã","ielts":1,"reviewed":false},{"id":"prv-0059","text":"Don't cross the bridge until you come to it.","vi":"Đừng lo trước về một khó khăn chưa thực sự xảy ra.","ex":"The repairs may be easy, so don't cross the bridge until you come to it.","exVi":"Việc sửa chữa có thể đơn giản, nên đừng lo trước khi vấn đề xuất hiện.","src":null,"level":"general","topics":["Tư duy","Rủi ro"],"reg":"not-applicable","equiv":"Đừng lo bò trắng răng","ielts":1,"reviewed":false},{"id":"prv-0060","text":"Don't put the cart before the horse.","vi":"Đừng làm việc sai trình tự hoặc vội tính đến bước sau khi bước trước chưa xong.","ex":"First confirm the venue; don't put the cart before the horse.","exVi":"Trước tiên hãy xác nhận địa điểm; đừng làm việc ngược trình tự.","src":null,"level":"general","topics":["Công việc","Kế hoạch"],"reg":"not-applicable","equiv":"Cầm đèn chạy trước ô tô","ielts":1,"reviewed":false},{"id":"prv-0061","text":"Every dog has its day.","vi":"Ai rồi cũng có lúc gặp thời hoặc đạt được thành công của mình.","ex":"The new café struggled at first, but every dog has its day.","exVi":"Quán cà phê mới ban đầu gặp khó, nhưng rồi ai cũng có lúc gặp thời.","src":null,"level":"general","topics":["Cơ hội","Kiên trì"],"reg":"not-applicable","equiv":"Ai rồi cũng có lúc gặp thời","ielts":1,"reviewed":false},{"id":"prv-0062","text":"Great minds think alike.","vi":"Những người có cách suy nghĩ tương đồng thường cùng nảy ra một ý tưởng.","ex":"We both suggested a reading club; great minds think alike.","exVi":"Cả hai chúng tôi đều đề xuất câu lạc bộ đọc sách; đúng là tư tưởng lớn gặp nhau.","src":null,"level":"general","topics":["Học tập","Hợp tác"],"reg":"not-applicable","equiv":"Tư tưởng lớn gặp nhau","ielts":1,"reviewed":false},{"id":"prv-0063","text":"Don't cry over spilled milk.","vi":"Đừng quá tiếc nuối điều đã xảy ra mà không thể thay đổi.","ex":"The booking is canceled, so don't cry over spilled milk; let's plan again.","exVi":"Chuyến đặt chỗ bị hủy rồi, đừng tiếc nuối nữa; chúng ta lên kế hoạch lại nhé.","src":null,"level":"general","topics":["Cảm xúc","Trải nghiệm"],"reg":"not-applicable","equiv":"Việc đã rồi, đừng tiếc nuối","ielts":1,"reviewed":false},{"id":"prv-0064","text":"A bird in the hand is worth two in the bush.","vi":"Một lợi ích chắc chắn thường đáng giá hơn những lựa chọn hấp dẫn nhưng chưa nắm được.","ex":"She kept her confirmed job offer; a bird in the hand is worth two in the bush.","exVi":"Cô giữ lời mời làm việc chắc chắn; lợi ích đang có thường đáng giá hơn cơ hội xa vời.","src":null,"level":"general","topics":["Công việc","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0065","text":"All roads lead to Rome.","vi":"Những cách làm khác nhau đôi khi vẫn có thể dẫn đến cùng một kết quả.","ex":"We tried several routes through the town; all roads lead to Rome.","exVi":"Chúng tôi thử vài con đường trong thị trấn; đường nào rồi cũng đến La Mã.","src":null,"level":"general","topics":["Lựa chọn","Du lịch"],"reg":"not-applicable","equiv":"Đường nào cũng về La Mã","ielts":1,"reviewed":false},{"id":"prv-0066","text":"A rolling stone gathers no moss.","vi":"Người thường xuyên đổi chỗ ở hoặc công việc có thể ít bị ràng buộc, nhưng khó xây dựng sự ổn định.","ex":"He changed jobs often; a rolling stone gathers no moss.","exVi":"Anh ấy thường xuyên đổi việc; người hay dịch chuyển thường khó tạo dựng sự ổn định.","src":null,"level":"general","topics":["Công việc","Đời sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0067","text":"Haste makes waste.","vi":"Làm quá vội dễ dẫn đến sai sót và tốn thêm công sức.","ex":"We checked the figures again; haste makes waste.","exVi":"Chúng tôi kiểm tra lại các con số; làm vội dễ khiến công sức bị lãng phí.","src":null,"level":"general","topics":["Thời gian","Công việc"],"reg":"not-applicable","equiv":"Dục tốc bất đạt","ielts":1,"reviewed":false},{"id":"prv-0068","text":"No news is good news.","vi":"Khi chưa có tin xấu, người ta thường hy vọng mọi việc vẫn ổn.","ex":"The repair team has not called, but no news is good news.","exVi":"Đội sửa chữa chưa gọi, nhưng chưa có tin xấu thì hy vọng mọi việc vẫn ổn.","src":null,"level":"general","topics":["Giao tiếp","Cảm xúc"],"reg":"not-applicable","equiv":"Chưa có tin xấu là tin tốt","ielts":1,"reviewed":false},{"id":"prv-0069","text":"The bigger they are, the harder they fall.","vi":"Người hoặc tổ chức càng mạnh, khi thất bại có thể càng chịu tác động lớn.","ex":"The underdog won the final; the bigger they are, the harder they fall.","exVi":"Đội bị đánh giá thấp thắng trận chung kết; kẻ mạnh đôi khi ngã đau hơn.","src":null,"level":"general","topics":["Thể thao","Thành công"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0070","text":"The best things in life are free.","vi":"Những điều quý giá nhất đôi khi không cần tiền để có được.","ex":"We watched the sunset together; the best things in life are free.","exVi":"Chúng tôi cùng ngắm hoàng hôn; những điều quý giá nhất đôi khi chẳng tốn tiền.","src":null,"level":"general","topics":["Giá trị sống","Đời sống"],"reg":"not-applicable","equiv":"Những điều quý giá nhất không mua được bằng tiền","ielts":1,"reviewed":false},{"id":"prv-0071","text":"The road to hell is paved with good intentions.","vi":"Chỉ có ý định tốt là chưa đủ; hành động thiếu cân nhắc vẫn có thể gây hậu quả xấu.","ex":"The plan caused trouble despite good intentions; the road to hell is paved with good intentions.","exVi":"Kế hoạch gây rắc rối dù xuất phát từ ý tốt; chỉ có thiện ý thôi chưa đủ.","src":null,"level":"general","topics":["Quyết định","Trách nhiệm"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0072","text":"First come, first served.","vi":"Ai đến trước sẽ được phục vụ hoặc nhận phần trước.","ex":"Workshop seats are limited and offered first come, first served.","exVi":"Số chỗ trong hội thảo có hạn và được xếp theo thứ tự đến trước.","src":null,"level":"general","topics":["Dịch vụ","Thời gian"],"reg":"not-applicable","equiv":"Ai đến trước được trước","ielts":1,"reviewed":false},{"id":"prv-0073","text":"If the shoe fits, wear it.","vi":"Nếu lời nhận xét thực sự đúng với mình, hãy thừa nhận điều đó.","ex":"I described the habit generally; if the shoe fits, wear it.","exVi":"Tôi chỉ nói chung về thói quen ấy; nếu thấy đúng với mình thì hãy tự nhận.","src":null,"level":"general","topics":["Giao tiếp","Tư duy"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0074","text":"A penny saved is a penny earned.","vi":"Tiền tiết kiệm được cũng có giá trị như tiền kiếm thêm.","ex":"She packed lunch instead of buying it; a penny saved is a penny earned.","exVi":"Cô tự chuẩn bị bữa trưa thay vì mua; tiết kiệm được đồng nào cũng quý đồng ấy.","src":null,"level":"general","topics":["Tiền bạc","Thói quen"],"reg":"not-applicable","equiv":"Tích tiểu thành đại","ielts":1,"reviewed":false},{"id":"prv-0075","text":"The apple doesn't fall far from the tree.","vi":"Con cái thường có nét tính cách hoặc sở thích giống cha mẹ.","ex":"Her daughter also loves astronomy; the apple doesn't fall far from the tree.","exVi":"Con gái cô cũng mê thiên văn; đúng là con cái thường giống cha mẹ.","src":null,"level":"general","topics":["Gia đình","Sở thích"],"reg":"not-applicable","equiv":"Con nhà tông không giống lông cũng giống cánh","ielts":1,"reviewed":false},{"id":"prv-0076","text":"It takes two to tango.","vi":"Một số tình huống hoặc mâu thuẫn cần sự tham gia của cả hai bên.","ex":"Both teammates missed the handoff; it takes two to tango.","exVi":"Cả hai đồng đội đều bỏ lỡ lượt chuyền; tình huống đó có phần trách nhiệm của cả đôi bên.","src":null,"level":"general","topics":["Hợp tác","Quan hệ"],"reg":"not-applicable","equiv":"Một bàn tay không vỗ nên tiếng","ielts":1,"reviewed":false},{"id":"prv-0077","text":"A little knowledge is a dangerous thing.","vi":"Hiểu biết sơ sài có thể khiến người ta quá tự tin và đưa ra kết luận sai.","ex":"He quoted one study as final proof; a little knowledge is a dangerous thing.","exVi":"Anh ấy xem một nghiên cứu là bằng chứng cuối cùng; hiểu biết sơ sài dễ gây ngộ nhận.","src":null,"level":"general","topics":["Học tập","Tư duy"],"reg":"not-applicable","equiv":"Biết nửa vời dễ sinh chủ quan","ielts":1,"reviewed":false},{"id":"prv-0078","text":"All work and no play makes Jack a dull boy.","vi":"Chỉ làm việc mà không nghỉ ngơi hay vui chơi dễ khiến cuộc sống mất cân bằng.","ex":"The interns need a free weekend; all work and no play makes Jack a dull boy.","exVi":"Các thực tập sinh cần một cuối tuần nghỉ ngơi; chỉ làm việc thì cuộc sống mất cân bằng.","src":null,"level":"general","topics":["Công việc","Sức khỏe"],"reg":"not-applicable","equiv":"Làm ra làm, chơi ra chơi","ielts":1,"reviewed":false},{"id":"prv-0079","text":"Still waters run deep.","vi":"Người ít nói có thể sở hữu hiểu biết hoặc suy nghĩ sâu sắc.","ex":"He rarely speaks in meetings; still waters run deep.","exVi":"Anh ấy ít phát biểu trong cuộc họp; người trầm lặng đôi khi suy nghĩ rất sâu sắc.","src":null,"level":"general","topics":["Con người","Tư duy"],"reg":"not-applicable","equiv":"Tĩnh thủy lưu thâm","ielts":1,"reviewed":false},{"id":"prv-0080","text":"You can't win them all.","vi":"Không thể thắng hoặc thành công trong mọi lần thử sức.","ex":"We lost the final match, but you can't win them all.","exVi":"Chúng tôi thua trận chung kết, nhưng đâu thể thắng trong mọi cuộc chơi.","src":null,"level":"general","topics":["Thể thao","Trải nghiệm"],"reg":"not-applicable","equiv":"Thắng không kiêu, bại không nản","ielts":1,"reviewed":false},{"id":"prv-0081","text":"The more, the merrier.","vi":"Càng có nhiều người tham gia thì cuộc vui càng thêm rộn ràng.","ex":"Invite your cousins too; the more, the merrier.","exVi":"Mời cả anh chị em họ của bạn nhé; càng đông càng vui.","src":null,"level":"general","topics":["Quan hệ","Sự kiện"],"reg":"not-applicable","equiv":"Càng đông càng vui","ielts":1,"reviewed":false},{"id":"prv-0082","text":"Enough is as good as a feast.","vi":"Khi đã có đủ dùng, thêm nữa chưa chắc đem lại lợi ích.","ex":"I stopped after one slice; enough is as good as a feast.","exVi":"Tôi dừng lại sau một lát bánh; vừa đủ đôi khi đã là tốt nhất.","src":null,"level":"general","topics":["Đồ ăn","Tư duy"],"reg":"not-applicable","equiv":"Biết đủ là đủ","ielts":1,"reviewed":false},{"id":"prv-0083","text":"If you want something done right, do it yourself.","vi":"Nếu muốn việc được làm theo tiêu chuẩn mình mong đợi, đôi khi cần tự tay thực hiện.","ex":"He repaired the shelf himself; if you want something done right, do it yourself.","exVi":"Anh tự sửa chiếc kệ; muốn việc đúng như mong đợi thì đôi khi phải tự làm.","src":null,"level":"general","topics":["Công việc","Trách nhiệm"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0084","text":"Waste not, want not.","vi":"Biết tiết kiệm và tránh lãng phí sẽ giúp ta không thiếu thốn về sau.","ex":"She saves leftover fabric; waste not, want not.","exVi":"Cô giữ lại vải thừa; biết tiết kiệm thì sau này sẽ ít thiếu thốn.","src":null,"level":"general","topics":["Tiền bạc","Môi trường"],"reg":"not-applicable","equiv":"Khéo ăn thì no, khéo co thì ấm","ielts":1,"reviewed":false},{"id":"prv-0085","text":"You can lead a horse to water, but you can't make it drink.","vi":"Ta có thể tạo cơ hội hoặc đưa ra lời khuyên, nhưng không thể ép người khác tiếp nhận.","ex":"I recommended the class, but you can lead a horse to water, but you can't make it drink.","exVi":"Tôi đã giới thiệu lớp học, nhưng không thể ép ai đó tự nguyện tham gia.","src":null,"level":"general","topics":["Học tập","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0086","text":"There's no time like the present.","vi":"Thời điểm tốt để bắt đầu việc cần làm thường là ngay bây giờ.","ex":"Let's begin the application now; there's no time like the present.","exVi":"Hãy bắt đầu hồ sơ ngay; chẳng lúc nào thích hợp hơn hiện tại.","src":null,"level":"general","topics":["Thời gian","Hành động"],"reg":"not-applicable","equiv":"Việc hôm nay chớ để ngày mai","ielts":1,"reviewed":false},{"id":"prv-0087","text":"Make hay while the sun shines.","vi":"Hãy tận dụng cơ hội khi điều kiện đang thuận lợi.","ex":"The forecast is sunny, so let's make hay while the sun shines.","exVi":"Dự báo trời nắng, nên hãy tranh thủ làm việc khi thời tiết thuận lợi.","src":null,"level":"general","topics":["Cơ hội","Thời tiết"],"reg":"not-applicable","equiv":"Chớp thời cơ","ielts":1,"reviewed":false},{"id":"prv-0088","text":"One man's trash is another man's treasure.","vi":"Thứ người này không còn cần có thể lại hữu ích hoặc quý giá với người khác.","ex":"She turned an old jar into a vase; one man's trash is another man's treasure.","exVi":"Cô biến chiếc lọ cũ thành bình hoa; đồ bỏ của người này có thể là báu vật của người khác.","src":null,"level":"general","topics":["Môi trường","Sáng tạo"],"reg":"not-applicable","equiv":"Của người chán, của người thèm","ielts":1,"reviewed":false},{"id":"prv-0089","text":"Familiarity breeds contempt.","vi":"Quá quen thuộc đôi khi khiến người ta xem nhẹ hoặc bớt trân trọng nhau.","ex":"They stopped appreciating their teammate; familiarity breeds contempt.","exVi":"Họ dần không còn trân trọng đồng đội; quá quen thuộc đôi khi khiến ta xem nhẹ nhau.","src":null,"level":"general","topics":["Quan hệ","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0090","text":"A little goes a long way.","vi":"Một lượng nhỏ cũng có thể tạo ra tác dụng đáng kể.","ex":"Add only a teaspoon; a little goes a long way.","exVi":"Chỉ thêm một thìa nhỏ thôi; một chút cũng có tác dụng đáng kể.","src":null,"level":"general","topics":["Đồ ăn","Đời sống"],"reg":"not-applicable","equiv":"Góp gió thành bão","ielts":1,"reviewed":false},{"id":"prv-0091","text":"The squeaky wheel gets the grease.","vi":"Vấn đề được nêu rõ và kiên trì thường dễ nhận được sự chú ý.","ex":"She kept reporting the broken heater; the squeaky wheel gets the grease.","exVi":"Cô liên tục báo máy sưởi bị hỏng; vấn đề được nhắc đến thường dễ được chú ý.","src":null,"level":"general","topics":["Giao tiếp","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0092","text":"A problem shared is a problem halved.","vi":"Chia sẻ khó khăn với người đáng tin có thể khiến gánh nặng tinh thần nhẹ hơn.","ex":"He told his study group about the workload; a problem shared is a problem halved.","exVi":"Anh kể với nhóm học về khối lượng bài; chia sẻ khó khăn giúp lòng nhẹ hơn.","src":null,"level":"general","topics":["Sức khỏe","Quan hệ"],"reg":"not-applicable","equiv":"Một vấn đề được chia sẻ sẽ nhẹ đi một nửa","ielts":1,"reviewed":false},{"id":"prv-0093","text":"Every little helps.","vi":"Dù nhỏ, mỗi sự đóng góp đều có thể tạo nên khác biệt.","ex":"I donated a small amount; every little helps.","exVi":"Tôi quyên góp một khoản nhỏ; dù ít thì mỗi phần đóng góp đều có ích.","src":null,"level":"general","topics":["Giá trị sống","Cộng đồng"],"reg":"not-applicable","equiv":"Tích tiểu thành đại","ielts":1,"reviewed":false},{"id":"prv-0094","text":"A man is known by the company he keeps.","vi":"Bạn bè và những người ta thường gắn bó có thể phản ánh phần nào con người ta.","ex":"His teammates volunteer weekly; a man is known by the company he keeps.","exVi":"Đồng đội của anh ấy tình nguyện mỗi tuần; bạn bè thường phần nào phản ánh con người ta.","src":null,"level":"general","topics":["Quan hệ","Con người"],"reg":"not-applicable","equiv":"Chọn bạn mà chơi","ielts":1,"reviewed":false},{"id":"prv-0095","text":"As you make your bed, so you must lie in it.","vi":"Ta phải chấp nhận hệ quả của những lựa chọn và hành động do mình tạo ra.","ex":"He ignored the warnings; as you make your bed, so you must lie in it.","exVi":"Anh ấy phớt lờ cảnh báo; đã chọn thế nào thì phải chấp nhận hệ quả ấy.","src":null,"level":"general","topics":["Quyết định","Trách nhiệm"],"reg":"not-applicable","equiv":"Gieo nhân nào gặt quả nấy","ielts":1,"reviewed":false},{"id":"prv-0096","text":"When the cat's away, the mice will play.","vi":"Khi người quản lý vắng mặt, những người khác có thể thoải mái hơn hoặc lơ là quy tắc.","ex":"The coach left the gym early; when the cat's away, the mice will play.","exVi":"Huấn luyện viên rời phòng tập sớm; khi người quản lý vắng mặt, mọi người dễ thoải mái hơn.","src":null,"level":"general","topics":["Công việc","Hành vi"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0097","text":"The pot calling the kettle black.","vi":"Chỉ trích người khác về một lỗi mà bản thân mình cũng mắc phải.","ex":"He criticized my late arrival, then arrived late himself; the pot calling the kettle black.","exVi":"Anh chê tôi đến muộn rồi hôm sau cũng đến muộn; đúng là người chê cũng mắc lỗi ấy.","src":null,"level":"general","topics":["Giao tiếp","Tư duy"],"reg":"not-applicable","equiv":"Chó chê mèo lắm lông","ielts":1,"reviewed":false},{"id":"prv-0098","text":"Out of debt, out of danger.","vi":"Thoát khỏi nợ nần giúp giảm bớt áp lực và rủi ro tài chính.","ex":"She paid the last bill; out of debt, out of danger.","exVi":"Cô trả xong hóa đơn cuối; hết nợ thì giảm được một phần áp lực.","src":null,"level":"general","topics":["Tiền bạc","Sức khỏe"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0099","text":"A word to the wise is enough.","vi":"Người biết suy xét có thể hiểu ý chỉ qua một lời nhắc ngắn.","ex":"I mentioned the deadline once; a word to the wise is enough.","exVi":"Tôi chỉ nhắc hạn chót một lần; người biết suy xét sẽ hiểu.","src":null,"level":"general","topics":["Giao tiếp","Học tập"],"reg":"not-applicable","equiv":"Nói một hiểu mười","ielts":1,"reviewed":false},{"id":"prv-0100","text":"One man's meat is another man's poison.","vi":"Điều hợp khẩu vị hoặc có ích với người này có thể không phù hợp với người khác.","ex":"I loved the soup, but one man's meat is another man's poison.","exVi":"Tôi thích món súp, nhưng khẩu vị mỗi người mỗi khác.","src":null,"level":"general","topics":["Đồ ăn","Sở thích"],"reg":"not-applicable","equiv":"Mỗi người một khẩu vị","ielts":1,"reviewed":false},{"id":"prv-0101","text":"All good things must come to an end.","vi":"Những điều tốt đẹp cũng có lúc kết thúc.","ex":"The exhibition closed on Sunday; all good things must come to an end.","exVi":"Triển lãm kết thúc vào Chủ nhật; điều tốt đẹp nào rồi cũng có lúc khép lại.","src":null,"level":"general","topics":["Thời gian","Trải nghiệm"],"reg":"not-applicable","equiv":"Cuộc vui nào rồi cũng tàn","ielts":1,"reviewed":false},{"id":"prv-0102","text":"One swallow does not make a summer.","vi":"Một dấu hiệu tích cực riêng lẻ chưa đủ chứng minh xu hướng tốt đã bền vững.","ex":"One warm afternoon is welcome, but one swallow does not make a summer.","exVi":"Một buổi chiều ấm áp thật dễ chịu, nhưng một dấu hiệu tốt chưa nói lên xu hướng lâu dài.","src":null,"level":"general","topics":["Tư duy","Thời tiết"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0103","text":"Better the devil you know than the devil you don't.","vi":"Đôi khi lựa chọn quen thuộc, dù chưa lý tưởng, có vẻ an toàn hơn điều hoàn toàn xa lạ.","ex":"They kept the familiar supplier; better the devil you know than the devil you don't.","exVi":"Họ tiếp tục làm việc với nhà cung cấp quen thuộc; điều đã biết đôi khi có vẻ ít rủi ro hơn.","src":null,"level":"general","topics":["Quyết định","Công việc"],"reg":"not-applicable","equiv":"Quen mặt dễ xử hơn người lạ","ielts":1,"reviewed":false},{"id":"prv-0104","text":"A change is as good as a rest.","vi":"Đổi sang một hoạt động khác cũng có thể giúp tinh thần hồi phục như nghỉ ngơi.","ex":"She switched to gardening after work; a change is as good as a rest.","exVi":"Tan làm, cô chuyển sang chăm vườn; đổi hoạt động cũng giúp tinh thần thư thái.","src":null,"level":"general","topics":["Sức khỏe","Sở thích"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0105","text":"A good beginning is half the battle.","vi":"Khởi đầu thuận lợi giúp việc còn lại dễ tiến triển hơn.","ex":"We made a clear plan first; a good beginning is half the battle.","exVi":"Trước tiên chúng tôi lập kế hoạch rõ ràng; khởi đầu tốt là đã thắng một nửa.","src":null,"level":"general","topics":["Công việc","Kế hoạch"],"reg":"not-applicable","equiv":"Đầu xuôi đuôi lọt","ielts":1,"reviewed":false},{"id":"prv-0106","text":"A friend to all is a friend to none.","vi":"Cố làm vừa lòng tất cả mọi người đôi khi khiến ta không xây dựng được tình bạn sâu sắc.","ex":"She stopped agreeing with everyone; a friend to all is a friend to none.","exVi":"Cô ấy thôi đồng ý với tất cả; cố làm bạn với mọi người có khi chẳng thân với ai.","src":null,"level":"general","topics":["Tình bạn","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0107","text":"Don't throw the baby out with the bathwater.","vi":"Đừng loại bỏ điều hữu ích chỉ vì muốn bỏ đi phần không tốt.","ex":"We revised the course carefully; don't throw the baby out with the bathwater.","exVi":"Chúng tôi chỉnh sửa khóa học cẩn thận; đừng vì bỏ điều chưa tốt mà bỏ luôn phần hữu ích.","src":null,"level":"general","topics":["Giáo dục","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0108","text":"He who laughs last laughs longest.","vi":"Kết quả cuối cùng mới cho thấy ai thực sự thành công.","ex":"They doubted her small start, but he who laughs last laughs longest.","exVi":"Họ nghi ngờ khởi đầu nhỏ bé của cô, nhưng người cười sau cùng mới là người cười lâu nhất.","src":null,"level":"general","topics":["Thành công","Kiên trì"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0109","text":"It never rains but it pours.","vi":"Khi một rắc rối xảy ra, đôi khi nhiều việc khó khăn khác cũng kéo đến cùng lúc.","ex":"My phone broke during the move; it never rains but it pours.","exVi":"Điện thoại hỏng đúng lúc chuyển nhà; đúng là họa thường kéo đến dồn dập.","src":null,"level":"general","topics":["Khó khăn","Đời sống"],"reg":"not-applicable","equiv":"Họa vô đơn chí","ielts":1,"reviewed":false},{"id":"prv-0110","text":"Live and let live.","vi":"Hãy tôn trọng cách sống và lựa chọn của người khác.","ex":"Their neighbors keep different hours, so they live and let live.","exVi":"Hàng xóm sinh hoạt giờ giấc khác nhau, nên họ tôn trọng lối sống của nhau.","src":null,"level":"general","topics":["Cộng đồng","Lối sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0111","text":"The devil is in the details.","vi":"Những chi tiết nhỏ có thể tạo ra vấn đề lớn nếu không được xem xét kỹ.","ex":"The budget looked fine until we checked the fees; the devil is in the details.","exVi":"Ngân sách có vẻ ổn cho đến khi chúng tôi kiểm tra lệ phí; vấn đề nằm ở các chi tiết.","src":null,"level":"general","topics":["Công việc","Tài chính"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0112","text":"The cobbler's children go barefoot.","vi":"Người giỏi chăm lo cho người khác đôi khi lại bỏ quên nhu cầu của gia đình mình.","ex":"He repairs phones all day, yet the cobbler's children go barefoot.","exVi":"Anh ấy sửa điện thoại cả ngày, vậy mà gia đình anh lại thiếu thiết bị tốt.","src":null,"level":"general","topics":["Gia đình","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0113","text":"There are plenty more fish in the sea.","vi":"Sau một cơ hội hoặc mối quan hệ không thành, vẫn còn nhiều lựa chọn khác.","ex":"She missed that internship, but there are plenty more fish in the sea.","exVi":"Cô ấy lỡ cơ hội thực tập đó, nhưng ngoài kia vẫn còn nhiều lựa chọn.","src":null,"level":"general","topics":["Cơ hội","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0114","text":"Don't bite off more than you can chew.","vi":"Đừng nhận nhiều việc hơn khả năng hoặc thời gian mình có thể đảm đương.","ex":"He chose two evening classes; don't bite off more than you can chew.","exVi":"Anh ấy chọn hai lớp buổi tối; đừng nhận quá nhiều so với sức mình.","src":null,"level":"general","topics":["Học tập","Quản lý thời gian"],"reg":"not-applicable","equiv":"Liệu cơm gắp mắm","ielts":1,"reviewed":false},{"id":"prv-0115","text":"Don't burn your bridges.","vi":"Đừng làm hỏng những mối quan hệ hoặc cơ hội mà sau này mình có thể cần.","ex":"She left the team politely; don't burn your bridges when changing jobs.","exVi":"Cô ấy rời nhóm một cách lịch sự; đổi việc thì đừng cắt đứt mọi quan hệ.","src":null,"level":"general","topics":["Công việc","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0116","text":"A drowning man will clutch at a straw.","vi":"Người tuyệt vọng có thể bám víu vào bất kỳ hy vọng nhỏ nhoi nào.","ex":"With rent due tomorrow, he accepted any shift; a drowning man will clutch at a straw.","exVi":"Tiền thuê nhà đến hạn ngày mai, anh nhận mọi ca làm; người tuyệt vọng sẽ bám vào chút hy vọng.","src":null,"level":"general","topics":["Khó khăn","Công việc"],"reg":"not-applicable","equiv":"Chết đuối vớ được cọc","ielts":1,"reviewed":false},{"id":"prv-0117","text":"You can catch more flies with honey than vinegar.","vi":"Thái độ tử tế thường thuyết phục người khác hiệu quả hơn sự gay gắt.","ex":"She asked calmly for a refund; you can catch more flies with honey than vinegar.","exVi":"Cô ấy bình tĩnh đề nghị hoàn tiền; lời nói nhẹ nhàng thường dễ thuyết phục hơn.","src":null,"level":"general","topics":["Giao tiếp","Dịch vụ"],"reg":"not-applicable","equiv":"Lời nói chẳng mất tiền mua, lựa lời mà nói cho vừa lòng nhau","ielts":1,"reviewed":false},{"id":"prv-0118","text":"There is no smoke without fire.","vi":"Một tin đồn hoặc dấu hiệu thường có nguyên do, dù cần kiểm tra trước khi kết luận.","ex":"Several staff reported the same issue; there is no smoke without fire.","exVi":"Nhiều nhân viên báo cùng một vấn đề; thường có lý do phía sau những dấu hiệu ấy.","src":null,"level":"general","topics":["Giao tiếp","Công việc"],"reg":"not-applicable","equiv":"Không có lửa làm sao có khói","ielts":1,"reviewed":false},{"id":"prv-0119","text":"A place for everything and everything in its place.","vi":"Sắp xếp đồ đạc đúng chỗ giúp không gian gọn gàng và dễ tìm kiếm.","ex":"After labeling the drawers, a place for everything and everything in its place.","exVi":"Sau khi dán nhãn các ngăn kéo, mọi thứ đều có chỗ của nó.","src":null,"level":"general","topics":["Nhà cửa","Thói quen"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0120","text":"A new broom sweeps clean.","vi":"Người mới nắm quyền hoặc bắt đầu công việc thường tạo ra nhiều thay đổi ban đầu.","ex":"The new manager simplified approvals; a new broom sweeps clean.","exVi":"Quản lý mới đơn giản hóa quy trình duyệt; người mới thường tạo thay đổi rõ rệt.","src":null,"level":"general","topics":["Công việc","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0121","text":"Charity begins at home.","vi":"Lòng tốt nên được thể hiện trước tiên với những người gần gũi và cần ta giúp đỡ.","ex":"Before funding distant projects, the group remembered that charity begins at home.","exVi":"Trước khi tài trợ dự án xa, nhóm nhớ rằng lòng tốt nên bắt đầu từ những người thân cận.","src":null,"level":"general","topics":["Gia đình","Cộng đồng"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0122","text":"He who pays the piper calls the tune.","vi":"Người chi trả thường có ảnh hưởng lớn đến cách một việc được thực hiện.","ex":"The sponsor chose the venue; he who pays the piper calls the tune.","exVi":"Nhà tài trợ chọn địa điểm; người trả tiền thường quyết định cuộc chơi.","src":null,"level":"general","topics":["Tài chính","Quyền quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0123","text":"There's many a slip between cup and lip.","vi":"Kế hoạch vẫn có thể gặp trục trặc trước khi hoàn tất, nên đừng vội cho rằng thành công đã chắc chắn.","ex":"The contract is nearly signed, but there's many a slip between cup and lip.","exVi":"Hợp đồng gần ký xong, nhưng vẫn có thể phát sinh trở ngại trước khi hoàn tất.","src":null,"level":"general","topics":["Kế hoạch","Thận trọng"],"reg":"not-applicable","equiv":"Nói trước bước không qua","ielts":1,"reviewed":false},{"id":"prv-0124","text":"Where there's life, there's hope.","vi":"Khi mọi việc chưa kết thúc, vẫn còn cơ hội để tìm hướng giải quyết.","ex":"The treatment is difficult, but where there's life, there's hope.","exVi":"Việc điều trị rất khó khăn, nhưng còn sống thì vẫn còn hy vọng.","src":null,"level":"general","topics":["Sức khỏe","Hy vọng"],"reg":"not-applicable","equiv":"Còn nước còn tát","ielts":1,"reviewed":false},{"id":"prv-0125","text":"Two is company, three's a crowd.","vi":"Một cuộc gặp riêng tư đôi khi dễ trò chuyện hơn khi có thêm người thứ ba.","ex":"They planned a quiet dinner for two; two is company, three's a crowd.","exVi":"Họ định ăn tối riêng yên tĩnh; hai người thì thân mật, thêm người thứ ba thành đông.","src":null,"level":"general","topics":["Quan hệ","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0126","text":"If you can't beat them, join them.","vi":"Khi không thể thay đổi một xu hướng, đôi khi tham gia vào đó là lựa chọn thực tế.","ex":"Everyone used digital notes, so I adapted; if you can't beat them, join them.","exVi":"Ai cũng dùng ghi chú số nên tôi thích nghi; không thắng được xu hướng thì hãy tham gia.","src":null,"level":"general","topics":["Công nghệ","Thích nghi"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0127","text":"A man's home is his castle.","vi":"Nhà là không gian riêng tư nơi mỗi người có quyền cảm thấy an toàn và tự chủ.","ex":"He values privacy at home; a man's home is his castle.","exVi":"Anh ấy coi trọng sự riêng tư ở nhà; nhà là không gian riêng của mỗi người.","src":null,"level":"general","topics":["Nhà cửa","Quyền riêng tư"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0128","text":"Better bend than break.","vi":"Linh hoạt trước áp lực đôi khi tốt hơn cố chấp đến mức thất bại.","ex":"The team adjusted its deadline; better bend than break.","exVi":"Nhóm điều chỉnh thời hạn; linh hoạt còn hơn cố quá rồi gãy đổ.","src":null,"level":"general","topics":["Thích nghi","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0129","text":"Barking dogs seldom bite.","vi":"Người hay đe dọa hoặc nói lớn chưa chắc sẽ thực sự hành động.","ex":"The critic complained loudly but stayed polite; barking dogs seldom bite.","exVi":"Người phê bình phàn nàn lớn tiếng nhưng vẫn lịch sự; chó sủa thường ít cắn.","src":null,"level":"general","topics":["Tính cách","Giao tiếp"],"reg":"not-applicable","equiv":"Chó sủa là chó không cắn","ielts":1,"reviewed":false},{"id":"prv-0130","text":"Many a true word is spoken in jest.","vi":"Một lời nói đùa đôi khi bộc lộ suy nghĩ thật của người nói.","ex":"His joke revealed his worry; many a true word is spoken in jest.","exVi":"Câu đùa của anh ấy để lộ nỗi lo; lời nói đùa đôi khi có ý thật.","src":null,"level":"general","topics":["Giao tiếp","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0131","text":"Forewarned is forearmed.","vi":"Biết trước nguy cơ giúp ta chuẩn bị và ứng phó tốt hơn.","ex":"We checked the weather before hiking; forewarned is forearmed.","exVi":"Chúng tôi kiểm tra thời tiết trước khi đi bộ đường dài; biết trước thì chuẩn bị tốt hơn.","src":null,"level":"general","topics":["Du lịch","Chuẩn bị"],"reg":"not-applicable","equiv":"Biết người biết ta, trăm trận trăm thắng","ielts":1,"reviewed":false},{"id":"prv-0132","text":"Slow and steady wins the race.","vi":"Tiến bộ đều đặn và kiên trì thường đưa ta đến đích.","ex":"She studied twenty minutes daily; slow and steady wins the race.","exVi":"Cô ấy học hai mươi phút mỗi ngày; chậm mà đều sẽ tới đích.","src":null,"level":"general","topics":["Học tập","Kiên trì"],"reg":"not-applicable","equiv":"Chậm mà chắc","ielts":1,"reviewed":false},{"id":"prv-0133","text":"It's always darkest before the dawn.","vi":"Giai đoạn khó khăn nhất đôi khi xuất hiện ngay trước khi tình hình cải thiện.","ex":"The project felt hopeless, but it's always darkest before the dawn.","exVi":"Dự án có vẻ bế tắc, nhưng khó khăn nhất đôi khi đến trước lúc bình minh.","src":null,"level":"general","topics":["Khó khăn","Hy vọng"],"reg":"not-applicable","equiv":"Qua cơn bĩ cực, đến hồi thái lai","ielts":1,"reviewed":false},{"id":"prv-0134","text":"Bad news travels fast.","vi":"Tin xấu thường lan truyền nhanh chóng giữa mọi người.","ex":"By lunchtime, the delay was known everywhere; bad news travels fast.","exVi":"Đến giờ trưa, ai cũng biết chuyến hàng bị trễ; tin xấu thường lan nhanh.","src":null,"level":"general","topics":["Truyền thông","Giao tiếp"],"reg":"not-applicable","equiv":"Tiếng dữ đồn xa","ielts":1,"reviewed":false},{"id":"prv-0135","text":"Make a virtue of necessity.","vi":"Hãy tìm cách biến điều bắt buộc hoặc bất tiện thành cơ hội có ích.","ex":"She chose to make a virtue of necessity and cycled daily.","exVi":"Cô chọn cách biến hoàn cảnh bắt buộc thành lợi ích và đạp xe mỗi ngày.","src":null,"level":"general","topics":["Thích nghi","Lối sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0136","text":"When one door closes, another opens.","vi":"Một cơ hội kết thúc có thể mở đường cho một cơ hội khác.","ex":"After the course ended, he found a new path; when one door closes, another opens.","exVi":"Sau khi khóa học kết thúc, anh tìm được hướng mới; cánh cửa này khép lại có thể mở ra cánh cửa khác.","src":null,"level":"general","topics":["Cơ hội","Thay đổi"],"reg":"not-applicable","equiv":"Trong cái rủi có cái may","ielts":1,"reviewed":false},{"id":"prv-0137","text":"Cut your coat according to your cloth.","vi":"Hãy chi tiêu và đặt kế hoạch phù hợp với nguồn lực mình có.","ex":"They chose a smaller venue; cut your coat according to your cloth.","exVi":"Họ chọn địa điểm nhỏ hơn; hãy liệu cơm gắp mắm.","src":null,"level":"general","topics":["Tài chính","Kế hoạch"],"reg":"not-applicable","equiv":"Liệu cơm gắp mắm","ielts":1,"reviewed":false},{"id":"prv-0138","text":"Don't carry coals to Newcastle.","vi":"Đừng mang thứ gì đến nơi vốn đã có dư thừa thứ đó.","ex":"She brought coffee to the café owner; don't carry coals to Newcastle.","exVi":"Cô mang cà phê đến cho chủ quán; đừng chở củi về rừng.","src":null,"level":"general","topics":["Du lịch","Thực phẩm"],"reg":"not-applicable","equiv":"Chở củi về rừng","ielts":1,"reviewed":false},{"id":"prv-0139","text":"Leave well enough alone.","vi":"Đừng cố sửa đổi điều đang ổn nếu việc can thiệp có thể khiến nó tệ hơn.","ex":"The old schedule works, so leave well enough alone.","exVi":"Lịch cũ vẫn hiệu quả, vậy đừng cố thay đổi cho phức tạp hơn.","src":null,"level":"general","topics":["Ra quyết định","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0140","text":"Old habits die hard.","vi":"Những thói quen lâu năm thường khó thay đổi.","ex":"He still checks paper maps; old habits die hard.","exVi":"Anh ấy vẫn xem bản đồ giấy; thói quen lâu năm quả thật khó bỏ.","src":null,"level":"general","topics":["Thói quen","Công nghệ"],"reg":"not-applicable","equiv":"Giang sơn dễ đổi, bản tính khó dời","ielts":1,"reviewed":false},{"id":"prv-0141","text":"There's honor among thieves.","vi":"Ngay cả trong một nhóm làm điều sai trái, các thành viên đôi khi vẫn tuân theo quy tắc riêng với nhau.","ex":"The smugglers kept their pact; there's honor among thieves.","exVi":"Những kẻ buôn lậu giữ thỏa thuận riêng; đôi khi giữa họ cũng có quy tắc.","src":null,"level":"general","topics":["Quan hệ","Đạo đức"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0142","text":"Fair exchange is no robbery.","vi":"Một cuộc trao đổi mà cả hai bên đều tự nguyện và nhận được giá trị tương xứng là công bằng.","ex":"They swapped shifts happily; fair exchange is no robbery.","exVi":"Họ vui vẻ đổi ca làm; trao đổi công bằng thì chẳng ai bị thiệt.","src":null,"level":"general","topics":["Công việc","Trao đổi"],"reg":"not-applicable","equiv":"Thuận mua vừa bán","ielts":1,"reviewed":false},{"id":"prv-0143","text":"A good name is better than riches.","vi":"Danh tiếng tốt và sự đáng tin quý giá hơn của cải vật chất.","ex":"She returned the lost wallet; a good name is better than riches.","exVi":"Cô trả lại chiếc ví bị mất; danh tiếng tốt quý hơn giàu sang.","src":null,"level":"general","topics":["Đạo đức","Tài chính"],"reg":"not-applicable","equiv":"Tốt danh hơn lành áo","ielts":1,"reviewed":false},{"id":"prv-0144","text":"You can't get blood from a stone.","vi":"Không thể lấy thêm nguồn lực từ một người hoặc nơi vốn đã cạn kiệt.","ex":"The budget is empty, and you can't get blood from a stone.","exVi":"Ngân sách đã cạn, không thể đòi thêm từ nơi chẳng còn gì.","src":null,"level":"general","topics":["Tài chính","Giới hạn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0145","text":"Beggars can't be choosers.","vi":"Khi chỉ có một lựa chọn, ta thường phải chấp nhận điều mình có.","ex":"She accepted the spare room; beggars can't be choosers.","exVi":"Cô nhận phòng còn trống; khi ít lựa chọn, ta phải chấp nhận điều mình có.","src":null,"level":"general","topics":["Lựa chọn","Đời sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0146","text":"If wishes were horses, beggars would ride.","vi":"Chỉ mong muốn thôi không biến điều ta muốn thành hiện thực; cần hành động cụ thể.","ex":"If wishes were horses, beggars would ride, so let's make a realistic plan.","exVi":"Ước muốn suông không đủ, vì vậy hãy lập một kế hoạch thực tế.","src":null,"level":"general","topics":["Mục tiêu","Hành động"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0147","text":"A fool and his money are soon parted.","vi":"Người thiếu suy xét có thể tiêu hết tiền rất nhanh.","ex":"He spent the bonus by Friday; a fool and his money are soon parted.","exVi":"Đến thứ Sáu anh đã tiêu hết tiền thưởng; người thiếu suy xét dễ tiêu sạch tiền.","src":null,"level":"general","topics":["Tài chính","Chi tiêu"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0148","text":"There's no such thing as a free lunch.","vi":"Điều có vẻ miễn phí thường vẫn đi kèm một cái giá hoặc sự đánh đổi.","ex":"The discount requires a long contract; there's no such thing as a free lunch.","exVi":"Ưu đãi này cần hợp đồng dài hạn; thứ có vẻ miễn phí thường vẫn có cái giá của nó.","src":null,"level":"general","topics":["Tài chính","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0149","text":"An empty vessel makes the most noise.","vi":"Người biết ít đôi khi lại nói nhiều hoặc tỏ ra chắc chắn nhất.","ex":"He spoke confidently without checking facts; an empty vessel makes the most noise.","exVi":"Anh nói rất tự tin mà chưa kiểm tra sự thật; người biết ít đôi khi nói nhiều nhất.","src":null,"level":"general","topics":["Giao tiếp","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0150","text":"It is easy to be wise after the event.","vi":"Sau khi biết kết quả, việc nhận ra điều lẽ ra nên làm thường trở nên dễ dàng.","ex":"After the match, everyone knew the right tactic; it is easy to be wise after the event.","exVi":"Sau trận đấu, ai cũng biết chiến thuật đúng; sau sự việc thì khôn ngoan thường dễ hơn.","src":null,"level":"general","topics":["Kinh nghiệm","Thể thao"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0151","text":"All is fair in love and war.","vi":"Trong tình yêu hoặc cạnh tranh quyết liệt, người ta thường cho rằng mọi cách đều có thể chấp nhận.","ex":"All is fair in love and war, she joked while bargaining for the last concert ticket.","exVi":"Cô đùa rằng trong tình yêu và cạnh tranh quyết liệt, ai cũng tìm cách giành phần mình.","src":null,"level":"general","topics":["Tình yêu","Cạnh tranh"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0152","text":"You can't make an omelette without breaking eggs.","vi":"Muốn đạt được kết quả tốt đôi khi phải chấp nhận một số tổn thất hoặc thay đổi cần thiết.","ex":"We replaced the old bridge carefully; you can't make an omelette without breaking eggs.","exVi":"Chúng tôi thay cây cầu cũ một cách cẩn trọng; muốn đổi mới đôi khi phải chấp nhận xáo trộn.","src":null,"level":"general","topics":["Thay đổi","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0153","text":"If you lie down with dogs, you get up with fleas.","vi":"Gần gũi với người có hành vi xấu có thể khiến ta bị ảnh hưởng hoặc gặp rắc rối.","ex":"He left the reckless group; if you lie down with dogs, you get up with fleas.","exVi":"Anh rời nhóm liều lĩnh; chơi với người xấu có thể khiến mình gặp rắc rối.","src":null,"level":"general","topics":["Quan hệ","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0154","text":"A bad penny always turns up.","vi":"Một người hoặc điều phiền toái dường như luôn quay trở lại vào lúc không mong muốn.","ex":"The faulty printer failed again; a bad penny always turns up.","exVi":"Chiếc máy in lỗi lại hỏng; điều phiền toái ấy dường như cứ quay lại.","src":null,"level":"general","topics":["Công nghệ","Rắc rối"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0155","text":"Little pitchers have big ears.","vi":"Trẻ nhỏ thường nghe và ghi nhớ nhiều điều người lớn tưởng rằng chúng không để ý.","ex":"The children heard our whispered plan; little pitchers have big ears.","exVi":"Bọn trẻ nghe thấy kế hoạch chúng tôi thì thầm; trẻ nhỏ thường để ý nhiều hơn ta nghĩ.","src":null,"level":"general","topics":["Gia đình","Trẻ em"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0156","text":"Don't wash your dirty linen in public.","vi":"Đừng đem chuyện riêng tư hoặc bất đồng nội bộ ra phơi bày trước công chúng.","ex":"Don't wash your dirty linen in public; discuss the disagreement privately.","exVi":"Đừng đem chuyện riêng ra công chúng; hãy trao đổi bất đồng một cách riêng tư.","src":null,"level":"general","topics":["Quan hệ","Quyền riêng tư"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0157","text":"Strike while the iron is hot.","vi":"Hãy tận dụng cơ hội khi điều kiện đang thuận lợi.","ex":"The weather cleared, so we planted immediately; strike while the iron is hot.","exVi":"Trời vừa tạnh nên chúng tôi gieo trồng ngay; hãy tận dụng lúc thuận lợi.","src":null,"level":"general","topics":["Cơ hội","Thời tiết"],"reg":"not-applicable","equiv":"Chớp thời cơ","ielts":1,"reviewed":false},{"id":"prv-0158","text":"Every man for himself and the devil take the hindmost.","vi":"Trong tình huống cạnh tranh khốc liệt, mỗi người có thể chỉ lo cứu lấy mình.","ex":"They rushed for the last seats; every man for himself and the devil take the hindmost.","exVi":"Họ tranh nhau những chỗ cuối cùng; trong cảnh hỗn loạn, ai cũng chỉ lo cho mình.","src":null,"level":"general","topics":["Cạnh tranh","Cộng đồng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0159","text":"The end justifies the means.","vi":"Một số người cho rằng kết quả tốt có thể biện minh cho cách thức đã dùng để đạt được nó.","ex":"He defended every shortcut, saying the end justifies the means.","exVi":"Anh biện hộ cho mọi đường tắt, cho rằng kết quả biện minh cho cách làm.","src":null,"level":"general","topics":["Đạo đức","Mục tiêu"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0160","text":"He who hesitates is lost.","vi":"Chần chừ quá lâu có thể khiến ta bỏ lỡ cơ hội.","ex":"She applied before the deadline; he who hesitates is lost.","exVi":"Cô nộp đơn trước hạn; chần chừ quá lâu có thể khiến ta lỡ cơ hội.","src":null,"level":"general","topics":["Cơ hội","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0161","text":"Give credit where credit is due.","vi":"Hãy công nhận và ghi nhận đóng góp của người thực sự xứng đáng.","ex":"The report improved after Mai's research; give credit where credit is due.","exVi":"Báo cáo tốt hơn nhờ nghiên cứu của Mai; hãy ghi nhận công sức xứng đáng.","src":null,"level":"general","topics":["Công việc","Công nhận"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0162","text":"There's no accounting for taste.","vi":"Sở thích của mỗi người khác nhau và đôi khi không thể giải thích bằng lý lẽ chung.","ex":"They chose opposite films; there's no accounting for taste.","exVi":"Họ chọn hai bộ phim trái ngược; sở thích mỗi người mỗi khác.","src":null,"level":"general","topics":["Sở thích","Giải trí"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0163","text":"The truth will out.","vi":"Sự thật cuối cùng thường được phát hiện, dù ban đầu có bị che giấu.","ex":"The cover story collapsed quickly; the truth will out.","exVi":"Lời giải thích giả tạo nhanh chóng sụp đổ; sự thật rồi sẽ lộ ra.","src":null,"level":"general","topics":["Sự thật","Giao tiếp"],"reg":"not-applicable","equiv":"Cây kim trong bọc lâu ngày cũng lòi ra","ielts":0,"reviewed":false},{"id":"prv-0164","text":"You win some, you lose some.","vi":"Trong cuộc sống, có lúc ta đạt được điều mong muốn và có lúc phải chấp nhận thất bại.","ex":"I missed the first train but caught the next; you win some, you lose some.","exVi":"Tôi lỡ chuyến tàu đầu nhưng bắt kịp chuyến sau; được cái này thì mất cái khác.","src":null,"level":"general","topics":["Thành công","Thất bại"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0165","text":"You can't make a silk purse out of a sow's ear.","vi":"Không thể biến vật liệu hoặc nguồn lực kém chất lượng thành thứ hoàn hảo chỉ bằng cách xử lý bề ngoài.","ex":"We polished the cheap material, but you can't make a silk purse out of a sow's ear.","exVi":"Chúng tôi đánh bóng vật liệu rẻ tiền, nhưng không thể biến thứ kém thành đồ hoàn hảo.","src":null,"level":"general","topics":["Chất lượng","Công việc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0166","text":"A miss is as good as a mile.","vi":"Dù chỉ hụt một chút, kết quả vẫn là không đạt được mục tiêu.","ex":"We arrived just after the doors closed; a miss is as good as a mile.","exVi":"Chúng tôi đến ngay sau khi cửa đóng; hụt một chút thì vẫn là lỡ mất.","src":null,"level":"general","topics":["Thời gian","Cơ hội"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0167","text":"If it sounds too good to be true, it probably is.","vi":"Một lời mời hứa hẹn quá hấp dẫn thường cần được kiểm tra kỹ vì có thể không đáng tin.","ex":"The offer promised no-risk returns; if it sounds too good to be true, it probably is.","exVi":"Lời mời hứa lợi nhuận lớn mà không có rủi ro; quá tốt để là thật thì nên thận trọng.","src":null,"level":"general","topics":["Tài chính","Thận trọng"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0168","text":"An idle brain is the devil's workshop.","vi":"Khi không có việc hữu ích để làm, người ta dễ nghĩ ra hoặc làm điều gây rắc rối.","ex":"He had no plans all afternoon; an idle brain is the devil's workshop.","exVi":"Cả buổi chiều anh không có kế hoạch gì; nhàn rỗi quá dễ sinh chuyện.","src":null,"level":"general","topics":["Thói quen","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0169","text":"A soft answer turns away wrath.","vi":"Một câu trả lời bình tĩnh và nhẹ nhàng có thể làm dịu cơn giận.","ex":"She answered the complaint calmly; a soft answer turns away wrath.","exVi":"Cô bình tĩnh trả lời lời phàn nàn; đáp lại nhẹ nhàng có thể làm dịu cơn giận.","src":null,"level":"general","topics":["Giao tiếp","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0170","text":"Great oaks from little acorns grow.","vi":"Những thành tựu lớn có thể bắt đầu từ những bước nhỏ.","ex":"Their tiny garden became a farm; great oaks from little acorns grow.","exVi":"Khu vườn nhỏ của họ thành nông trại; thành tựu lớn có thể bắt đầu rất nhỏ.","src":null,"level":"general","topics":["Thành công","Môi trường"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0171","text":"It takes a thief to catch a thief.","vi":"Người từng hiểu rõ một hành vi sai trái đôi khi biết cách nhận ra hoặc ngăn chặn nó.","ex":"The detective consulted an ex-thief; it takes a thief to catch a thief.","exVi":"Thám tử hỏi ý kiến một cựu kẻ trộm; người hiểu cách làm sai có thể nhận ra nó.","src":null,"level":"general","topics":["Pháp luật","Kinh nghiệm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0172","text":"A bird may be known by its song.","vi":"Đặc điểm hoặc cách thể hiện thường cho biết một người hay sự vật thuộc về đâu.","ex":"She recognized his hometown by his accent; a bird may be known by its song.","exVi":"Cô nhận ra quê anh qua giọng nói; một người thường bộc lộ nguồn gốc qua cách thể hiện.","src":null,"level":"general","topics":["Quê hương","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0173","text":"It takes all sorts to make a world.","vi":"Xã hội cần những người có tính cách và quan điểm khác nhau.","ex":"The festival welcomed every personality; it takes all sorts to make a world.","exVi":"Lễ hội chào đón đủ mọi tính cách; xã hội cần nhiều kiểu người khác nhau.","src":null,"level":"general","topics":["Cộng đồng","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0174","text":"Better to be alone than in bad company.","vi":"Ở một mình đôi khi tốt hơn là ở cạnh những người có ảnh hưởng xấu.","ex":"He declined the rude invitation; better to be alone than in bad company.","exVi":"Anh từ chối lời mời khiếm nhã; một mình còn hơn ở cạnh bạn xấu.","src":null,"level":"general","topics":["Tình bạn","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0175","text":"If the mountain will not come to Muhammad, Muhammad must go to the mountain.","vi":"Nếu hoàn cảnh không thay đổi theo ý ta, ta cần chủ động tìm cách thích nghi hoặc tiến tới mục tiêu.","ex":"The tutor adapted; if the mountain will not come to Muhammad, Muhammad must go to the mountain.","exVi":"Gia sư chủ động điều chỉnh; nếu hoàn cảnh không đổi, ta cần tự tìm đường đến mục tiêu.","src":null,"level":"general","topics":["Thích nghi","Học tập"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0176","text":"In the country of the blind, the one-eyed man is king.","vi":"Trong môi trường thiếu hiểu biết, người chỉ biết nhiều hơn một chút cũng có thể nổi bật.","ex":"Among beginners, in the country of the blind, the one-eyed man is king.","exVi":"Giữa những người mới bắt đầu, người biết hơn một chút cũng dễ trở nên nổi bật.","src":null,"level":"general","topics":["Giáo dục","Kỹ năng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0177","text":"The best defense is a good offense.","vi":"Chủ động hành động đôi khi là cách hiệu quả nhất để tự bảo vệ hoặc ngăn vấn đề.","ex":"The team addressed rumors early; the best defense is a good offense.","exVi":"Nhóm xử lý tin đồn từ sớm; chủ động hành động đôi khi là cách tự bảo vệ tốt nhất.","src":null,"level":"general","topics":["Giải quyết vấn đề","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0178","text":"You can't please everyone.","vi":"Không thể làm hài lòng tất cả mọi người cùng một lúc.","ex":"You can't please everyone, so choose the plan that serves most people.","exVi":"Không thể làm hài lòng tất cả, nên hãy chọn phương án phục vụ được nhiều người nhất.","src":null,"level":"general","topics":["Quan hệ","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0179","text":"Misery loves company.","vi":"Người đang buồn hoặc gặp khó khăn thường thấy dễ chịu hơn khi biết người khác cũng có trải nghiệm tương tự.","ex":"They laughed about the failed project; misery loves company.","exVi":"Họ cùng cười về dự án thất bại; chia sẻ khó khăn với người hiểu mình có thể thấy nhẹ lòng.","src":null,"level":"general","topics":["Cảm xúc","Tình bạn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0180","text":"Experience is the best teacher.","vi":"Trải nghiệm thực tế thường dạy ta những điều khó học chỉ qua lý thuyết.","ex":"After the mistake, she learned a lesson; experience is the best teacher.","exVi":"Sau sai sót, cô rút ra bài học; trải nghiệm thực tế thường dạy ta nhiều nhất.","src":null,"level":"general","topics":["Học tập","Kinh nghiệm"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0181","text":"If you don't ask, you don't get.","vi":"Nếu không chủ động đề nghị hoặc tìm kiếm, ta khó có được điều mình cần.","ex":"If you don't ask, you don't get, so she requested flexible hours.","exVi":"Nếu không đề nghị thì khó đạt được điều mong muốn, nên cô xin giờ làm linh hoạt.","src":null,"level":"general","topics":["Giao tiếp","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0182","text":"In for a penny, in for a pound.","vi":"Khi đã bắt đầu một việc và chấp nhận rủi ro, người ta thường quyết định theo đuổi đến cùng.","ex":"He bought the ticket and continued; in for a penny, in for a pound.","exVi":"Anh đã mua vé rồi tiếp tục hành trình; đã bắt đầu thì quyết theo đến cùng.","src":null,"level":"general","topics":["Quyết tâm","Tài chính"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0183","text":"Silence is golden.","vi":"Đôi khi im lặng khôn ngoan hơn là nói những điều không cần thiết.","ex":"They let the silence rest; silence is golden.","exVi":"Họ để khoảng lặng tự nhiên; đôi khi im lặng là lựa chọn tốt nhất.","src":null,"level":"general","topics":["Giao tiếp","Thận trọng"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0184","text":"You get what you pay for.","vi":"Chất lượng hoặc độ bền thường tương xứng với số tiền đã bỏ ra.","ex":"The inexpensive headphones broke quickly; you get what you pay for.","exVi":"Tai nghe giá rẻ nhanh hỏng; chất lượng thường đi đôi với số tiền bỏ ra.","src":null,"level":"general","topics":["Tài chính","Công nghệ"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0185","text":"People who live in glass houses shouldn't throw stones.","vi":"Đừng chỉ trích người khác về khuyết điểm mà chính mình cũng mắc phải.","ex":"People who live in glass houses shouldn't throw stones, especially before checking their own actions.","exVi":"Người sống trong nhà kính không nên ném đá; trước khi chỉ trích, hãy nhìn lại mình.","src":null,"level":"general","topics":["Tính cách","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0186","text":"Give someone an inch and they'll take a mile.","vi":"Nếu chỉ nhượng bộ một chút, đôi khi người khác sẽ đòi hỏi thêm rất nhiều.","ex":"The small extension became a full month; give someone an inch and they'll take a mile.","exVi":"Việc gia hạn ngắn thành cả tháng; nhượng bộ một chút đôi khi dẫn đến đòi hỏi thêm.","src":null,"level":"general","topics":["Ranh giới","Quan hệ"],"reg":"not-applicable","equiv":"Được đằng chân, lân đằng đầu","ielts":1,"reviewed":false},{"id":"prv-0187","text":"Jack of all trades, master of none.","vi":"Người biết làm nhiều việc có thể không thật sự thành thạo việc nào.","ex":"He can repair bikes, code, and cook: jack of all trades, master of none.","exVi":"Anh biết sửa xe, lập trình và nấu ăn: biết nhiều việc nhưng chưa tinh thông việc nào.","src":null,"level":"general","topics":["Kỹ năng","Công việc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0188","text":"The first step is the hardest.","vi":"Bắt đầu một việc thường là phần khó nhất.","ex":"She finally opened the textbook; the first step is the hardest.","exVi":"Cuối cùng cô cũng mở sách giáo khoa; bắt đầu thường là phần khó nhất.","src":null,"level":"general","topics":["Học tập","Mục tiêu"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0189","text":"Desperate times call for desperate measures.","vi":"Khi hoàn cảnh đặc biệt khó khăn, đôi khi cần những biện pháp mạnh hoặc khác thường.","ex":"With the road closed, desperate times call for desperate measures.","exVi":"Khi con đường bị đóng, tình thế khó khăn buộc chúng tôi phải tìm biện pháp khác thường.","src":null,"level":"general","topics":["Khó khăn","Giải quyết vấn đề"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0190","text":"Pride comes before a fall.","vi":"Quá kiêu ngạo hoặc tự tin có thể khiến ta mắc sai lầm và thất bại.","ex":"He ignored every warning; pride comes before a fall.","exVi":"Anh bỏ ngoài tai mọi lời cảnh báo; kiêu ngạo quá mức dễ dẫn đến thất bại.","src":null,"level":"general","topics":["Tính cách","Thất bại"],"reg":"not-applicable","equiv":"Trèo cao ngã đau","ielts":1,"reviewed":false},{"id":"prv-0191","text":"No one can serve two masters.","vi":"Khó có thể trung thành trọn vẹn với hai bên có yêu cầu hoặc mục tiêu xung đột.","ex":"The consultant faced conflicting demands; no one can serve two masters.","exVi":"Chuyên gia tư vấn nhận những yêu cầu mâu thuẫn; khó có thể phục vụ trọn vẹn hai bên.","src":null,"level":"general","topics":["Công việc","Lựa chọn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0192","text":"Easier said than done.","vi":"Nói rằng một việc nên làm thường dễ hơn nhiều so với thực hiện nó.","ex":"Saving money sounds simple, but it's easier said than done.","exVi":"Tiết kiệm tiền nghe có vẻ đơn giản, nhưng nói thì dễ hơn làm.","src":null,"level":"general","topics":["Tài chính","Thói quen"],"reg":"not-applicable","equiv":"Nói thì dễ, làm mới khó","ielts":1,"reviewed":false},{"id":"prv-0193","text":"Do as you would be done by.","vi":"Hãy đối xử với người khác theo cách mà mình mong họ đối xử với mình.","ex":"She treated the new colleague fairly; do as you would be done by.","exVi":"Cô đối xử công bằng với đồng nghiệp mới; hãy đối xử với người khác như mình muốn được đối xử.","src":null,"level":"general","topics":["Đạo đức","Quan hệ"],"reg":"not-applicable","equiv":"Ở hiền gặp lành","ielts":1,"reviewed":false},{"id":"prv-0194","text":"You can't make bricks without straw.","vi":"Không thể hoàn thành một việc nếu thiếu những nguồn lực hoặc điều kiện thiết yếu.","ex":"The builders need materials; you can't make bricks without straw.","exVi":"Thợ xây cần vật liệu; thiếu điều kiện thiết yếu thì không thể hoàn thành công việc.","src":null,"level":"general","topics":["Công việc","Nguồn lực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0195","text":"Necessity knows no law.","vi":"Khi nhu cầu cấp bách, con người đôi khi sẵn sàng vượt qua những giới hạn thông thường.","ex":"Hungry travelers shared the last meal; necessity knows no law.","exVi":"Những người đi đường đói bụng chia nhau bữa ăn cuối; lúc cấp bách, người ta dễ phá lệ.","src":null,"level":"general","topics":["Nhu cầu","Đời sống"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0196","text":"Don't teach your grandmother to suck eggs.","vi":"Đừng cố chỉ dẫn cho người có nhiều kinh nghiệm hơn mình về điều họ đã biết rõ.","ex":"He explained basic cooking to the chef; don't teach your grandmother to suck eggs.","exVi":"Anh giải thích cách nấu ăn cơ bản cho đầu bếp; đừng múa rìu qua mắt thợ.","src":null,"level":"general","topics":["Kinh nghiệm","Giao tiếp"],"reg":"not-applicable","equiv":"Múa rìu qua mắt thợ","ielts":0,"reviewed":false},{"id":"prv-0197","text":"What's sauce for the goose is sauce for the gander.","vi":"Điều được xem là đúng hoặc chấp nhận được với người này cũng nên áp dụng cho người khác.","ex":"If staff can work remotely, what's sauce for the goose is sauce for the gander.","exVi":"Nếu nhân viên được làm từ xa, quy tắc ấy nên áp dụng công bằng cho mọi người.","src":null,"level":"general","topics":["Công bằng","Công việc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0198","text":"Don't put new wine in old bottles.","vi":"Đừng áp dụng một ý tưởng mới trong khuôn khổ cũ vốn không phù hợp với nó.","ex":"The team redesigned the process; don't put new wine in old bottles.","exVi":"Nhóm thiết kế lại quy trình; đừng nhồi ý tưởng mới vào khuôn khổ cũ không phù hợp.","src":null,"level":"general","topics":["Đổi mới","Công việc"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0199","text":"No one knows the value of water until the well runs dry.","vi":"Người ta thường chỉ nhận ra giá trị của một điều thiết yếu khi không còn có nó.","ex":"Locals learned that no one knows the value of water until the well runs dry.","exVi":"Ngôi làng quý nước sạch hơn sau khi giếng cạn; ta thường nhận ra giá trị khi đã mất đi.","src":null,"level":"general","topics":["Môi trường","Nước"],"reg":"not-applicable","equiv":"Mất bò mới lo làm chuồng","ielts":1,"reviewed":false},{"id":"prv-0200","text":"If you want peace, prepare for war.","vi":"Muốn duy trì hòa bình, đôi khi cần chuẩn bị đủ khả năng tự bảo vệ.","ex":"The country strengthened its defenses; if you want peace, prepare for war.","exVi":"Quốc gia củng cố phòng thủ; muốn giữ hòa bình, đôi khi cần chuẩn bị để tự bảo vệ.","src":null,"level":"general","topics":["An toàn","Lịch sử"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0201","text":"Money can't buy happiness.","vi":"Tiền bạc không thể tự mình đem lại niềm vui, sự gắn kết hay cảm giác mãn nguyện.","ex":"He had a large house but felt lonely; money can't buy happiness.","exVi":"Anh có căn nhà lớn nhưng vẫn cô đơn; tiền bạc không thể mua được hạnh phúc.","src":null,"level":"general","topics":["Hạnh phúc","Tài chính"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0202","text":"You can have too much of a good thing.","vi":"Ngay cả điều tốt cũng có thể trở nên quá mức nếu ta sử dụng hoặc tận hưởng không điều độ.","ex":"I love spicy food, but you can have too much of a good thing.","exVi":"Tôi thích đồ ăn cay, nhưng điều gì tốt cũng có thể trở nên quá mức.","src":null,"level":"general","topics":["Ăn uống","Sức khỏe"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0203","text":"There is a time and place for everything.","vi":"Mỗi việc có thời điểm và hoàn cảnh phù hợp để thực hiện.","ex":"Jokes can wait until the meeting ends; there is a time and place for everything.","exVi":"Có thể đợi đến khi họp xong mới đùa; việc gì cũng có thời điểm và chỗ phù hợp.","src":null,"level":"general","topics":["Thời gian","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0204","text":"The more you have, the more you want.","vi":"Khi đã có nhiều hơn, con người đôi khi lại muốn nhiều hơn nữa.","ex":"After buying one device, he wanted another; the more you have, the more you want.","exVi":"Mua xong một thiết bị, anh lại muốn thêm cái nữa; có nhiều rồi đôi khi lại muốn nhiều hơn.","src":null,"level":"general","topics":["Tiêu dùng","Tài chính"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0205","text":"A closed mouth catches no flies.","vi":"Im lặng đôi khi giúp ta tránh được những rắc rối do nói quá nhiều hoặc không đúng lúc.","ex":"He stayed quiet during the argument; a closed mouth catches no flies.","exVi":"Anh giữ im lặng trong cuộc tranh cãi; ít nói đôi khi giúp tránh rắc rối.","src":null,"level":"general","topics":["Giao tiếp","Thận trọng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0206","text":"The devil looks after his own.","vi":"Người có tính cách xấu hoặc làm điều sai đôi khi dường như vẫn gặp may.","ex":"He escaped another penalty; the devil looks after his own.","exVi":"Anh lại thoát bị phạt; đôi khi người làm điều xấu vẫn gặp may.","src":null,"level":"general","topics":["Đạo đức","Công bằng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0207","text":"Every man has his price.","vi":"Ai cũng có thể bị thuyết phục bằng một lợi ích đủ lớn, theo cách nhìn đầy hoài nghi này.","ex":"The offer changed his vote; every man has his price.","exVi":"Lời đề nghị khiến anh đổi phiếu; theo cách nhìn hoài nghi, ai cũng có giá của mình.","src":null,"level":"general","topics":["Đạo đức","Tài chính"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0208","text":"A small leak will sink a great ship.","vi":"Một vấn đề nhỏ nếu bị bỏ qua có thể gây hậu quả nghiêm trọng về sau.","ex":"A tiny crack spread across the hull; a small leak will sink a great ship.","exVi":"Vết nứt nhỏ lan khắp thân tàu; vấn đề nhỏ bị bỏ qua có thể gây hậu quả lớn.","src":null,"level":"general","topics":["Thận trọng","An toàn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0209","text":"A man's word is his bond.","vi":"Người đáng tin sẽ giữ lời hứa và chịu trách nhiệm về điều mình đã nói.","ex":"She promised to return the keys; a man's word is his bond.","exVi":"Cô hứa sẽ trả chìa khóa; người đáng tin luôn giữ lời.","src":null,"level":"general","topics":["Trách nhiệm","Đạo đức"],"reg":"not-applicable","equiv":"Quân tử nhất ngôn","ielts":1,"reviewed":false},{"id":"prv-0210","text":"If you play with fire, you get burned.","vi":"Đùa với nguy hiểm hoặc hành động thiếu thận trọng có thể khiến ta chịu hậu quả.","ex":"He ignored the safety rules; if you play with fire, you get burned.","exVi":"Anh phớt lờ quy tắc an toàn; đùa với nguy hiểm thì có thể tự chuốc hậu quả.","src":null,"level":"general","topics":["An toàn","Ra quyết định"],"reg":"not-applicable","equiv":"Chơi dao có ngày đứt tay","ielts":1,"reviewed":false},{"id":"prv-0211","text":"Lookers-on see most of the game.","vi":"Người đứng ngoài đôi khi nhìn nhận tình huống khách quan hơn người đang ở trong cuộc.","ex":"The coach noticed the pattern from the sidelines; lookers-on see most of the game.","exVi":"Huấn luyện viên nhận ra quy luật từ ngoài sân; người đứng ngoài đôi khi nhìn rõ hơn.","src":null,"level":"general","topics":["Thể thao","Góc nhìn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0212","text":"Virtue is its own reward.","vi":"Làm điều tốt có giá trị tự thân, ngay cả khi không nhận được phần thưởng.","ex":"She helped without expecting praise; virtue is its own reward.","exVi":"Cô giúp đỡ mà không mong được khen; làm điều tốt tự nó đã có giá trị.","src":null,"level":"general","topics":["Đạo đức","Cộng đồng"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0213","text":"Lend your money and lose your friend.","vi":"Cho bạn bè vay tiền có thể làm tổn hại tình cảm nếu việc hoàn trả gây tranh cãi.","ex":"Their unpaid loan ended the friendship; lend your money and lose your friend.","exVi":"Khoản vay không được trả đã kết thúc tình bạn; cho vay đôi khi làm sứt mẻ quan hệ.","src":null,"level":"general","topics":["Tài chính","Tình bạn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0214","text":"Love makes the world go round.","vi":"Tình yêu và sự quan tâm giúp con người tìm thấy động lực và ý nghĩa trong cuộc sống.","ex":"They volunteered together; love makes the world go round.","exVi":"Họ cùng làm tình nguyện; tình yêu thương và sự quan tâm giúp cuộc sống thêm ý nghĩa.","src":null,"level":"general","topics":["Tình yêu","Cộng đồng"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0215","text":"The longest way round is the shortest way home.","vi":"Đi con đường vòng hoặc chậm rãi đôi khi giúp ta đến đích nhanh và an toàn hơn.","ex":"We took the quiet route and avoided traffic; the longest way round is the shortest way home.","exVi":"Chúng tôi đi đường yên tĩnh và tránh tắc xe; đường vòng đôi khi lại nhanh hơn.","src":null,"level":"general","topics":["Du lịch","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0216","text":"Never say never.","vi":"Đừng vội khẳng định rằng một việc sẽ không bao giờ xảy ra.","ex":"He once disliked camping, but never say never.","exVi":"Trước đây anh không thích cắm trại, nhưng đừng bao giờ nói là không thể thay đổi.","src":null,"level":"general","topics":["Thay đổi","Sở thích"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0217","text":"Be careful what you wish for; you might get it.","vi":"Hãy suy nghĩ kỹ về mong muốn của mình vì khi đạt được, nó có thể kéo theo trách nhiệm hoặc khó khăn.","ex":"He regretted leading; be careful what you wish for, you might get it.","exVi":"Anh xin làm trưởng nhóm rồi lại hối tiếc; hãy cân nhắc điều mình mong muốn vì có thể sẽ đạt được.","src":null,"level":"general","topics":["Mục tiêu","Trách nhiệm"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0218","text":"What you don't know can't hurt you.","vi":"Có người cho rằng điều mình không biết sẽ không khiến mình lo lắng hoặc đau khổ.","ex":"He preferred not to read the rumors; what you don't know can't hurt you.","exVi":"Anh không muốn đọc tin đồn; đôi khi không biết lại giúp ta bớt lo lắng.","src":null,"level":"general","topics":["Cảm xúc","Thông tin"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0219","text":"A cat may look at a king.","vi":"Ngay cả người bình thường cũng có quyền quan sát hoặc bày tỏ ý kiến với người có địa vị cao.","ex":"The student questioned the principal; a cat may look at a king.","exVi":"Học sinh đặt câu hỏi với hiệu trưởng; người bình thường cũng có quyền lên tiếng.","src":null,"level":"general","topics":["Giáo dục","Quyền bình đẳng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0220","text":"The exception that proves the rule.","vi":"Một trường hợp ngoại lệ đôi khi làm nổi bật một quy luật chung.","ex":"Most shops close early, but this late-night café is the exception that proves the rule.","exVi":"Hầu hết cửa hàng đóng cửa sớm, còn quán cà phê mở khuya này càng làm nổi bật quy luật ấy.","src":null,"level":"general","topics":["Quy tắc","Khác biệt"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0221","text":"It's never too late to mend.","vi":"Dù đã mắc sai lầm, ta vẫn có thể sửa chữa hoặc cải thiện tình hình.","ex":"They apologized after years apart; it's never too late to mend.","exVi":"Sau nhiều năm xa cách, họ xin lỗi nhau; sửa chữa mối quan hệ không bao giờ là quá muộn.","src":null,"level":"general","topics":["Quan hệ","Thay đổi"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0222","text":"Love is blind.","vi":"Khi yêu, người ta đôi khi không nhận ra những khuyết điểm hoặc vấn đề rõ ràng của đối phương.","ex":"She overlooked his careless habits; love is blind.","exVi":"Cô bỏ qua những thói quen bất cẩn của anh; khi yêu, người ta đôi khi không nhìn rõ khuyết điểm.","src":null,"level":"general","topics":["Tình yêu","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0223","text":"Only time will tell.","vi":"Cần chờ thêm thời gian mới biết kết quả hoặc sự thật sẽ ra sao.","ex":"The new routine may help; only time will tell.","exVi":"Thói quen mới có thể có ích; phải chờ thời gian mới biết.","src":null,"level":"general","topics":["Thời gian","Kết quả"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0224","text":"Hope for the best, prepare for the worst.","vi":"Hãy giữ hy vọng nhưng vẫn chuẩn bị cho khả năng không thuận lợi.","ex":"We packed extra medicine; hope for the best, prepare for the worst.","exVi":"Chúng tôi mang thêm thuốc; hãy hy vọng điều tốt nhất nhưng chuẩn bị cho tình huống xấu nhất.","src":null,"level":"general","topics":["Hy vọng","Chuẩn bị"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0225","text":"Be penny-wise and pound-foolish.","vi":"Chỉ tiết kiệm những khoản nhỏ nhưng lại bỏ qua chi phí lớn có thể khiến ta tốn kém hơn.","ex":"We chose the cheapest bulb and replaced it twice; be penny-wise and pound-foolish.","exVi":"Chúng tôi chọn bóng đèn rẻ nhất rồi phải thay hai lần; tiết kiệm lặt vặt đôi khi lại tốn kém.","src":null,"level":"general","topics":["Tài chính","Mua sắm"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0226","text":"Do not run before you can walk.","vi":"Hãy học những điều cơ bản trước khi cố làm việc khó hơn.","ex":"The team learned the basics first; do not run before you can walk.","exVi":"Nhóm học các kiến thức cơ bản trước; đừng vội làm việc khó khi chưa vững nền tảng.","src":null,"level":"general","topics":["Học tập","Phát triển"],"reg":"not-applicable","equiv":"Chưa học bò đã lo học chạy","ielts":1,"reviewed":false},{"id":"prv-0227","text":"God helps those who help themselves.","vi":"Muốn đạt được điều mình mong muốn, ta cần chủ động nỗ lực thay vì chỉ chờ đợi.","ex":"She applied for several grants; God helps those who help themselves.","exVi":"Cô nộp đơn xin một số khoản tài trợ; muốn thành công thì cần chủ động nỗ lực.","src":null,"level":"general","topics":["Nỗ lực","Mục tiêu"],"reg":"not-applicable","equiv":"Có công mài sắt, có ngày nên kim","ielts":1,"reviewed":false},{"id":"prv-0228","text":"Let the buyer beware.","vi":"Người mua cần tự tìm hiểu và kiểm tra kỹ trước khi quyết định mua hàng.","ex":"Before buying from an unknown seller, let the buyer beware.","exVi":"Trước khi mua của người bán chưa rõ uy tín, người mua nên tự kiểm tra kỹ.","src":null,"level":"general","topics":["Mua sắm","Thận trọng"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0229","text":"Cleanliness is next to godliness.","vi":"Giữ gìn vệ sinh thân thể và không gian sống là điều quan trọng và đáng coi trọng.","ex":"Grandma insisted on daily cleaning; cleanliness is next to godliness.","exVi":"Bà luôn nhắc phải dọn dẹp mỗi ngày; giữ gìn sạch sẽ là điều rất quan trọng.","src":null,"level":"general","topics":["Nhà cửa","Sức khỏe"],"reg":"not-applicable","equiv":"Nhà sạch thì mát, bát sạch ngon cơm","ielts":1,"reviewed":false},{"id":"prv-0230","text":"If at first you don't succeed, try, try again.","vi":"Nếu chưa thành công ngay từ đầu, hãy tiếp tục thử với sự kiên trì.","ex":"The first design failed; if at first you don't succeed, try, try again.","exVi":"Bản thiết kế đầu tiên chưa đạt; nếu chưa thành công, hãy kiên trì thử lại.","src":null,"level":"general","topics":["Kiên trì","Công việc"],"reg":"not-applicable","equiv":"Thất bại là mẹ thành công","ielts":1,"reviewed":false},{"id":"prv-0231","text":"A bad beginning makes a bad ending.","vi":"Khởi đầu cẩu thả có thể khiến phần còn lại của công việc gặp nhiều vấn đề.","ex":"We ignored the early warning; a bad beginning makes a bad ending.","exVi":"Chúng tôi bỏ qua dấu hiệu cảnh báo ban đầu; khởi đầu tệ dễ dẫn đến kết quả tệ.","src":null,"level":"general","topics":["Công việc","Kế hoạch"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0232","text":"Measure twice, cut once.","vi":"Hãy kiểm tra cẩn thận trước khi thực hiện việc khó sửa lại hoặc không thể đảo ngược.","ex":"The carpenter checked both lengths; measure twice, cut once.","exVi":"Người thợ mộc kiểm tra hai lần số đo; hãy chắc chắn trước khi cắt.","src":null,"level":"general","topics":["Công việc","Thận trọng"],"reg":"not-applicable","equiv":"Cẩn tắc vô ưu","ielts":1,"reviewed":false},{"id":"prv-0233","text":"Practice what you preach.","vi":"Hãy làm theo những điều mình khuyên người khác nên làm.","ex":"The coach arrived early; practice what you preach.","exVi":"Huấn luyện viên đến sớm; hãy làm đúng những điều mình vẫn khuyên người khác.","src":null,"level":"general","topics":["Trách nhiệm","Công việc"],"reg":"not-applicable","equiv":"Nói đi đôi với làm","ielts":1,"reviewed":false},{"id":"prv-0234","text":"A lie has no legs.","vi":"Lời nói dối khó đứng vững lâu và thường sớm bị phát hiện.","ex":"The rumor collapsed quickly; a lie has no legs.","exVi":"Tin đồn nhanh chóng bị bác bỏ; lời nói dối khó tồn tại lâu.","src":null,"level":"general","topics":["Sự thật","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0235","text":"Money is a good servant but a bad master.","vi":"Tiền bạc hữu ích khi được quản lý tốt, nhưng có thể gây hại nếu nó chi phối mọi lựa chọn.","ex":"Money is a good servant but a bad master when it controls every choice.","exVi":"Tiền bạc là công cụ tốt nhưng là ông chủ tồi khi nó chi phối mọi lựa chọn.","src":null,"level":"general","topics":["Tài chính","Lối sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0236","text":"You can't run with the hare and hunt with the hounds.","vi":"Không thể cùng lúc ủng hộ hai phía đối lập hoặc làm hài lòng cả hai bên trong một xung đột.","ex":"He tried to please both teams; you can't run with the hare and hunt with the hounds.","exVi":"Anh cố làm hài lòng cả hai đội; không thể cùng lúc đứng về hai phía đối lập.","src":null,"level":"general","topics":["Lựa chọn","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0237","text":"The last straw breaks the camel's back.","vi":"Một phiền toái nhỏ cuối cùng có thể khiến người đã chịu đựng quá nhiều không thể tiếp tục.","ex":"Another delay arrived; the last straw breaks the camel's back.","exVi":"Lại thêm một lần chậm trễ; sự việc nhỏ cuối cùng có thể khiến người ta không chịu nổi nữa.","src":null,"level":"general","topics":["Cảm xúc","Khó khăn"],"reg":"not-applicable","equiv":"Tức nước vỡ bờ","ielts":1,"reviewed":false},{"id":"prv-0238","text":"Fine feathers make fine birds.","vi":"Trang phục đẹp có thể khiến vẻ ngoài của một người trông chỉn chu và ấn tượng hơn.","ex":"He wore a tailored suit; fine feathers make fine birds.","exVi":"Anh mặc bộ vest may đo; trang phục đẹp làm vẻ ngoài thêm chỉn chu.","src":null,"level":"general","topics":["Thời trang","Ấn tượng"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0239","text":"The longest day must have an end.","vi":"Ngay cả giai đoạn khó khăn hoặc kéo dài nhất rồi cũng sẽ kết thúc.","ex":"The wait felt endless, but the longest day must have an end.","exVi":"Thời gian chờ đợi tưởng như vô tận, nhưng ngày dài nhất rồi cũng sẽ qua.","src":null,"level":"general","topics":["Hy vọng","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0240","text":"There is no royal road to learning.","vi":"Không có lối tắt nào thay thế được việc học tập nghiêm túc và kiên trì.","ex":"She studied every chapter; there is no royal road to learning.","exVi":"Cô học từng chương; không có con đường tắt nào thay thế việc học chăm chỉ.","src":null,"level":"general","topics":["Học tập","Kiên trì"],"reg":"not-applicable","equiv":"Không thầy đố mày làm nên","ielts":0,"reviewed":false},{"id":"prv-0241","text":"A tree is known by its fruit.","vi":"Có thể đánh giá một người hoặc sự vật qua kết quả và hành động mà họ tạo ra.","ex":"Their generous actions showed their values; a tree is known by its fruit.","exVi":"Những hành động hào phóng cho thấy giá trị của họ; hãy nhìn quả để biết cây.","src":null,"level":"general","topics":["Tính cách","Đạo đức"],"reg":"not-applicable","equiv":"Xem quả biết cây","ielts":1,"reviewed":false},{"id":"prv-0242","text":"A cat has nine lives.","vi":"Mèo dường như có thể thoát khỏi nhiều tình huống nguy hiểm; câu này cũng ví người hay gặp may.","ex":"A cat has nine lives, and Milo proved it after another safe escape.","exVi":"Mèo có chín mạng, và Milo lại chứng minh điều đó sau một lần thoát hiểm an toàn.","src":null,"level":"general","topics":["Động vật","May mắn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0243","text":"The walls have ears.","vi":"Hãy cẩn thận khi nói chuyện riêng vì có thể có người khác đang nghe.","ex":"Keep your voice low; the walls have ears.","exVi":"Hãy nói nhỏ thôi; có thể có người khác đang nghe.","src":null,"level":"general","topics":["Quyền riêng tư","Giao tiếp"],"reg":"not-applicable","equiv":"Vách có tai","ielts":1,"reviewed":false},{"id":"prv-0244","text":"A word spoken is past recalling.","vi":"Một khi đã nói ra, lời nói có thể gây hậu quả mà ta không thể hoàn toàn rút lại.","ex":"He regretted the insult; a word spoken is past recalling.","exVi":"Anh hối tiếc vì lời xúc phạm; lời đã nói ra thì không thể thu lại hoàn toàn.","src":null,"level":"general","topics":["Giao tiếp","Trách nhiệm"],"reg":"not-applicable","equiv":"Lời nói như tên bắn","ielts":1,"reviewed":false},{"id":"prv-0245","text":"Variety is the spice of life.","vi":"Sự đa dạng giúp cuộc sống trở nên thú vị và bớt đơn điệu.","ex":"She joined a pottery class; variety is the spice of life.","exVi":"Cô tham gia lớp gốm; sự đa dạng khiến cuộc sống thú vị hơn.","src":null,"level":"general","topics":["Sở thích","Lối sống"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0246","text":"Any publicity is good publicity.","vi":"Được chú ý, kể cả vì điều tiêu cực, đôi khi vẫn tốt hơn là không ai biết đến.","ex":"The review was harsh, but any publicity is good publicity for a new café.","exVi":"Bài đánh giá khá gay gắt, nhưng một quán cà phê mới được chú ý vẫn tốt hơn là vô danh.","src":null,"level":"general","topics":["Truyền thông","Kinh doanh"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0247","text":"No good deed goes unpunished.","vi":"Câu nói mỉa mai rằng việc tốt đôi khi lại khiến người giúp gặp rắc rối hoặc thiệt thòi.","ex":"I stayed late to help and missed my bus; no good deed goes unpunished.","exVi":"Tôi ở lại muộn để giúp rồi lỡ chuyến xe; làm việc tốt đôi khi cũng gặp rắc rối.","src":null,"level":"general","topics":["Quan hệ","Hài hước"],"reg":"not-applicable","equiv":"Làm ơn mắc oán","ielts":0,"reviewed":false},{"id":"prv-0248","text":"If you can't stand the heat, get out of the kitchen.","vi":"Nếu không chịu được áp lực của một việc, hãy cân nhắc dừng lại thay vì chỉ than phiền.","ex":"If you can't stand the heat, get out of the kitchen; this job has tight deadlines.","exVi":"Nếu không chịu được áp lực thì nên cân nhắc nghỉ; công việc này có hạn chót gấp.","src":null,"level":"general","topics":["Công việc","Áp lực"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0249","text":"Discretion is the better part of valour.","vi":"Biết thận trọng và tránh rủi ro không cần thiết đôi khi khôn ngoan hơn liều lĩnh.","ex":"We postponed the climb because discretion is the better part of valour.","exVi":"Chúng tôi hoãn chuyến leo núi vì thận trọng vẫn khôn ngoan hơn mạo hiểm.","src":null,"level":"general","topics":["An toàn","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0250","text":"Time heals all wounds.","vi":"Nỗi đau và khó khăn thường dịu bớt theo thời gian.","ex":"She needed space to grieve; time heals all wounds.","exVi":"Cô cần thời gian để nguôi ngoai; thời gian sẽ giúp nỗi đau dịu lại.","src":null,"level":"general","topics":["Sức khỏe tinh thần","Thời gian"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0251","text":"United we stand, divided we fall.","vi":"Đoàn kết giúp một tập thể vững mạnh; chia rẽ khiến mọi người dễ thất bại.","ex":"The neighbors shared supplies; united we stand, divided we fall.","exVi":"Hàng xóm chia sẻ vật dụng; đoàn kết thì vững mạnh, chia rẽ thì suy yếu.","src":null,"level":"general","topics":["Cộng đồng","Quan hệ"],"reg":"not-applicable","equiv":"Đoàn kết thì sống, chia rẽ thì chết","ielts":1,"reviewed":false},{"id":"prv-0252","text":"An ounce of prevention is worth a pound of cure.","vi":"Chủ động phòng tránh thường dễ dàng và ít tốn kém hơn xử lý hậu quả.","ex":"We back up our files weekly; an ounce of prevention is worth a pound of cure.","exVi":"Chúng tôi sao lưu tệp mỗi tuần; phòng ngừa trước thường tốt hơn khắc phục sau.","src":null,"level":"general","topics":["Sức khỏe","Công nghệ"],"reg":"not-applicable","equiv":"Phòng bệnh hơn chữa bệnh","ielts":1,"reviewed":false},{"id":"prv-0253","text":"Fools rush in where angels fear to tread.","vi":"Người thiếu suy xét đôi khi lao vào những việc mà người thận trọng sẽ tránh.","ex":"He invested without research; fools rush in where angels fear to tread.","exVi":"Anh ấy đầu tư mà không tìm hiểu; người khờ thường liều ở nơi người khôn biết tránh.","src":null,"level":"general","topics":["Ra quyết định","Tài chính"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0254","text":"The enemy of my enemy is my friend.","vi":"Hai bên vốn đối địch có thể hợp tác khi cùng gặp một đối thủ chung.","ex":"Two rival teams joined forces against a common threat; the enemy of my enemy is my friend.","exVi":"Hai đội đối thủ hợp sức trước một mối đe dọa chung; kẻ thù của kẻ thù có thể thành đồng minh.","src":null,"level":"general","topics":["Quan hệ","Chiến lược"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0255","text":"The customer is always right.","vi":"Trong kinh doanh, câu này nhấn mạnh tầm quan trọng của việc lắng nghe và giữ khách hàng hài lòng.","ex":"Our staff listen carefully because the customer is always right.","exVi":"Nhân viên lắng nghe cẩn thận vì khách hàng luôn cần được tôn trọng.","src":null,"level":"general","topics":["Kinh doanh","Giao tiếp"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0256","text":"Opportunity knocks but once.","vi":"Một cơ hội tốt có thể không xuất hiện lần nữa, vì vậy nên cân nhắc nắm bắt đúng lúc.","ex":"She accepted the scholarship quickly; opportunity knocks but once.","exVi":"Cô nhanh chóng nhận học bổng; cơ hội tốt đôi khi chỉ đến một lần.","src":null,"level":"general","topics":["Cơ hội","Giáo dục"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0257","text":"Hunger is the best sauce.","vi":"Khi đói, người ta thường thấy món ăn giản dị cũng ngon miệng hơn.","ex":"After a long hike, plain rice tasted wonderful; hunger is the best sauce.","exVi":"Sau chuyến đi bộ dài, cơm trắng cũng ngon tuyệt; khi đói thì món giản dị cũng ngon.","src":null,"level":"general","topics":["Đồ ăn","Du lịch"],"reg":"not-applicable","equiv":"Đói ăn gì cũng ngon","ielts":1,"reviewed":false},{"id":"prv-0258","text":"There are two sides to every story.","vi":"Trước khi kết luận về một bất đồng, nên lắng nghe quan điểm của các bên liên quan.","ex":"I heard both colleagues before deciding; there are two sides to every story.","exVi":"Tôi nghe cả hai đồng nghiệp trước khi quyết định; mỗi câu chuyện đều có nhiều góc nhìn.","src":null,"level":"general","topics":["Giao tiếp","Truyền thông"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0259","text":"What can't be cured must be endured.","vi":"Khi một khó khăn không thể thay đổi, đôi khi ta cần chấp nhận và kiên nhẫn vượt qua.","ex":"The delay was unavoidable, so what can't be cured must be endured.","exVi":"Việc trì hoãn là không tránh khỏi, nên chúng tôi đành chấp nhận và kiên nhẫn.","src":null,"level":"general","topics":["Sức khỏe","Kiên nhẫn"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0260","text":"What's done is done.","vi":"Việc đã xảy ra thì không thể thay đổi; ta nên chấp nhận và tập trung vào bước tiếp theo.","ex":"We apologized and repaired the damage; what's done is done.","exVi":"Chúng tôi đã xin lỗi và sửa chữa thiệt hại; chuyện đã rồi thì nên hướng tới bước tiếp.","src":null,"level":"general","topics":["Thời gian","Trách nhiệm"],"reg":"not-applicable","equiv":"Chuyện đã rồi","ielts":1,"reviewed":false},{"id":"prv-0261","text":"The truth is stranger than fiction.","vi":"Đôi khi chuyện có thật lại khó tin và kỳ lạ hơn những gì người ta tưởng tượng.","ex":"The rescue story sounded unbelievable, but the truth is stranger than fiction.","exVi":"Câu chuyện giải cứu nghe khó tin, nhưng chuyện thật đôi khi còn lạ hơn hư cấu.","src":null,"level":"general","topics":["Truyền thông","Trải nghiệm"],"reg":"not-applicable","equiv":"Chuyện thật như đùa","ielts":1,"reviewed":false},{"id":"prv-0262","text":"Patience is a virtue.","vi":"Kiên nhẫn là một đức tính đáng quý, nhất là khi kết quả cần thời gian.","ex":"He waited calmly for the results; patience is a virtue.","exVi":"Anh bình tĩnh chờ kết quả; kiên nhẫn là một đức tính đáng quý.","src":null,"level":"general","topics":["Kiên nhẫn","Tính cách"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0263","text":"Beauty is only skin deep.","vi":"Ngoại hình không quan trọng bằng phẩm chất và tính cách bên trong.","ex":"The film reminds us that beauty is only skin deep; kindness matters more.","exVi":"Bộ phim nhắc ta rằng ngoại hình chỉ là vẻ ngoài; lòng tốt quan trọng hơn.","src":null,"level":"general","topics":["Ngoại hình","Tính cách"],"reg":"not-applicable","equiv":"Tốt gỗ hơn tốt nước sơn","ielts":1,"reviewed":false},{"id":"prv-0264","text":"Good things come in small packages.","vi":"Một thứ không cần lớn hay phô trương mới có thể có giá trị.","ex":"The tiny bakery makes excellent bread; good things come in small packages.","exVi":"Tiệm bánh nhỏ làm bánh rất ngon; thứ tốt không nhất thiết phải to lớn.","src":null,"level":"general","topics":["Chất lượng","Đồ ăn"],"reg":"not-applicable","equiv":"Nhỏ mà có võ","ielts":1,"reviewed":false},{"id":"prv-0265","text":"It's an ill wind that blows nobody any good.","vi":"Ngay cả một biến cố xấu đôi khi cũng đem lại lợi ích cho ai đó.","ex":"The storm hurt our field but filled the reservoir; it's an ill wind that blows nobody any good.","exVi":"Cơn bão làm hư ruộng nhưng bổ sung nước cho hồ chứa; trong cái rủi đôi khi có cái may.","src":null,"level":"general","topics":["Thời tiết","Khó khăn"],"reg":"not-applicable","equiv":"Trong cái rủi có cái may","ielts":0,"reviewed":false},{"id":"prv-0266","text":"What goes up must come down.","vi":"Điều gì tăng lên cũng có thể giảm xuống; thành công hay giá cả đều có lúc đổi chiều.","ex":"The company grew quickly, but its leaders knew what goes up must come down.","exVi":"Công ty phát triển nhanh, nhưng ban lãnh đạo hiểu rằng mọi thứ đều có thể đổi chiều.","src":null,"level":"general","topics":["Thay đổi","Kinh doanh"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0267","text":"Third time's the charm.","vi":"Sau hai lần chưa thành công, lần thử thứ ba có thể đem lại kết quả tốt.","ex":"After two failed attempts, she tried again; third time's the charm.","exVi":"Sau hai lần thất bại, cô thử lại; lần thứ ba có thể sẽ thành công.","src":null,"level":"general","topics":["Kiên trì","Thành công"],"reg":"not-applicable","equiv":"Quá tam ba bận","ielts":1,"reviewed":false},{"id":"prv-0268","text":"Don't throw good money after bad.","vi":"Đừng tiếp tục bỏ tiền vào một việc đã thất bại chỉ vì tiếc khoản đã mất.","ex":"We stopped repairing the old laptop; don't throw good money after bad.","exVi":"Chúng tôi ngừng sửa chiếc máy cũ; đừng tiếp tục tốn tiền chỉ vì đã lỡ đầu tư.","src":null,"level":"general","topics":["Tài chính","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0269","text":"A hungry man is an angry man.","vi":"Khi đói, con người thường dễ cáu kỉnh hơn.","ex":"The hike lasted longer than expected; a hungry man is an angry man.","exVi":"Chuyến đi bộ kéo dài hơn dự kiến; khi đói người ta thường dễ cáu kỉnh.","src":null,"level":"general","topics":["Đồ ăn","Cảm xúc"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0270","text":"Don't change horses in midstream.","vi":"Đừng thay đổi người hoặc kế hoạch chủ chốt khi một quá trình quan trọng đang diễn ra.","ex":"The project is halfway done, so don't change horses in midstream.","exVi":"Dự án đã hoàn thành một nửa, vì vậy đừng đổi người hay kế hoạch giữa chừng.","src":null,"level":"general","topics":["Công việc","Kế hoạch"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0271","text":"When in doubt, leave it out.","vi":"Nếu không chắc một chi tiết có phù hợp hay không, tốt hơn nên bỏ nó đi.","ex":"The caption sounded confusing, so when in doubt, leave it out.","exVi":"Chú thích nghe khó hiểu, nên khi phân vân thì tốt hơn hãy bỏ đi.","src":null,"level":"general","topics":["Giao tiếp","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0272","text":"Live and learn.","vi":"Trải nghiệm giúp ta rút ra bài học, thường là sau một sai lầm hoặc bất ngờ.","ex":"I missed the last train once; live and learn.","exVi":"Tôi từng lỡ chuyến tàu cuối; trải nghiệm ấy dạy tôi phải kiểm tra giờ tàu.","src":null,"level":"general","topics":["Trải nghiệm","Học tập"],"reg":"not-applicable","equiv":"Đi một ngày đàng, học một sàng khôn","ielts":1,"reviewed":false},{"id":"prv-0273","text":"Least said, soonest mended.","vi":"Một chuyện rắc rối đôi khi sẽ dễ lắng xuống hơn nếu mọi người không tiếp tục nhắc lại.","ex":"They stopped discussing the mistake; least said, soonest mended.","exVi":"Họ ngừng bàn về sai lầm ấy; ít nhắc lại có thể giúp mọi chuyện sớm êm xuôi.","src":null,"level":"general","topics":["Giao tiếp","Quan hệ"],"reg":"not-applicable","equiv":null,"ielts":0,"reviewed":false},{"id":"prv-0274","text":"When the going gets tough, the tough get going.","vi":"Khi hoàn cảnh trở nên khó khăn, người kiên cường sẽ chủ động hành động để vượt qua.","ex":"When the going gets tough, the tough get going, so our team focused on solutions.","exVi":"Khi tình hình khó khăn, người kiên cường bắt tay hành động, nên nhóm chúng tôi tập trung tìm giải pháp.","src":null,"level":"general","topics":["Khó khăn","Kiên trì"],"reg":"not-applicable","equiv":"Lửa thử vàng, gian nan thử sức","ielts":1,"reviewed":false},{"id":"prv-0275","text":"Don't cut off your nose to spite your face.","vi":"Đừng vì tức giận muốn làm khó người khác mà chọn cách cuối cùng gây thiệt hại cho chính mình.","ex":"Don't cut off your nose to spite your face, even when you're angry.","exVi":"Đừng vì đang giận mà chọn cách cuối cùng khiến bản thân chịu thiệt.","src":null,"level":"general","topics":["Cảm xúc","Ra quyết định"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0276","text":"Accidents will happen.","vi":"Đây là câu thường dùng để an ủi sau một sự cố và nhắc rằng đôi khi tai nạn khó tránh.","ex":"We cleaned up the spill and reminded everyone that accidents will happen.","exVi":"Chúng tôi lau chỗ nước đổ và nhắc mọi người rằng đôi khi sự cố vẫn xảy ra.","src":null,"level":"general","topics":["Sự kiện","An toàn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0277","text":"Think before you speak.","vi":"Hãy cân nhắc lời nói trước khi phát biểu để tránh làm người khác tổn thương hoặc gây hiểu lầm.","ex":"Think before you speak, especially when the discussion gets tense.","exVi":"Hãy suy nghĩ trước khi nói, nhất là khi cuộc trao đổi trở nên căng thẳng.","src":null,"level":"general","topics":["Giao tiếp","Cảm xúc"],"reg":"not-applicable","equiv":"Uốn lưỡi bảy lần trước khi nói","ielts":1,"reviewed":false},{"id":"prv-0278","text":"There's a first time for everything.","vi":"Ai rồi cũng sẽ có lần đầu trải nghiệm một việc mới hoặc chưa từng làm.","ex":"I had never tried scuba diving, but there's a first time for everything.","exVi":"Tôi chưa từng lặn biển, nhưng việc gì rồi cũng có lần đầu.","src":null,"level":"general","topics":["Trải nghiệm","Du lịch"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0279","text":"Everything in moderation.","vi":"Tận hưởng hoặc sử dụng mọi thứ ở mức vừa phải thường tốt hơn là thái quá.","ex":"She enjoys coffee, but everything in moderation helps her sleep well.","exVi":"Cô thích uống cà phê, nhưng dùng vừa phải giúp cô ngủ ngon hơn.","src":null,"level":"general","topics":["Sức khỏe","Đồ ăn"],"reg":"not-applicable","equiv":null,"ielts":1,"reviewed":false},{"id":"prv-0280","text":"April showers bring May flowers.","vi":"Mưa tháng Tư đem đến hoa tháng Năm; câu này cũng gợi rằng giai đoạn khó khăn có thể mở đường cho điều tốt đẹp.","ex":"I kept studying through the rainy month; April showers bring May flowers.","exVi":"Tôi vẫn học đều trong tháng mưa; sau giai đoạn khó khăn có thể sẽ đến điều tốt đẹp.","src":null,"level":"general","topics":["Thời tiết","Hy vọng"],"reg":"not-applicable","equiv":"Sau cơn mưa trời lại sáng","ielts":0,"reviewed":false},{"id":"prv-0281","text":"A guilty conscience needs no accuser.","vi":"Người biết mình có lỗi thường tự nhận ra hoặc để lộ lỗi lầm mà không cần ai buộc tội.","ex":"He confessed before anyone questioned him; a guilty conscience needs no accuser.","exVi":"Anh thú nhận trước khi bị ai hỏi; người có tật thường tự thấy bất an.","src":null,"level":"general","topics":["Trách nhiệm","Đạo đức"],"reg":"not-applicable","equiv":"Có tật giật mình","ielts":0,"reviewed":false},{"id":"prv-0282","text":"Business before pleasure.","vi":"Nên ưu tiên công việc và trách nhiệm trước khi dành thời gian cho vui chơi.","ex":"I planned a study session before the film; business before pleasure.","exVi":"Tôi lên kế hoạch học trước khi xem phim; nên ưu tiên việc cần làm trước.","src":null,"level":"general","topics":["Công việc","Học tập","Thời gian"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0283","text":"Where there's muck there's brass.","vi":"Công việc bẩn thỉu hoặc khó chịu đôi khi đem lại nguồn thu nhập đáng kể.","ex":"My uncle says where there's muck there's brass when discussing recycling work.","exVi":"Chú tôi hay nói công việc vất vả đôi khi lại đem đến nguồn thu nhập tốt.","src":null,"level":"general","topics":["Công việc","Tiền bạc","Môi trường"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0284","text":"There's no rest for the wicked.","vi":"Câu nói đùa khi phải tiếp tục làm việc dù đã rất mệt.","ex":"We finished one report and began another; there's no rest for the wicked.","exVi":"Chúng tôi vừa xong một báo cáo đã bắt đầu bản khác; đúng là chẳng được nghỉ.","src":null,"level":"general","topics":["Công việc","Sức khỏe","Thời gian"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0285","text":"Time is money.","vi":"Thời gian rất quý; lãng phí thời gian cũng có thể đồng nghĩa với mất cơ hội kiếm tiền.","ex":"We took the direct train because time is money during a work trip.","exVi":"Chúng tôi đi tàu thẳng vì trong chuyến công tác, thời gian là tiền bạc.","src":null,"level":"general","topics":["Thời gian","Công việc","Tiền bạc"],"reg":"not-applicable","equiv":"Thời gian là vàng","ielts":1,"reviewed":false},{"id":"prv-0286","text":"Cheaters never prosper.","vi":"Gian lận có thể đem lại lợi ích trước mắt nhưng thường dẫn đến hậu quả về sau.","ex":"The teacher reminded us that cheaters never prosper after the exam.","exVi":"Sau kỳ thi, giáo viên nhắc rằng gian lận không thể đem lại thành công lâu dài.","src":null,"level":"general","topics":["Học tập","Đạo đức","Thành công"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0287","text":"You can't take it with you.","vi":"Của cải vật chất không thể mang theo sau khi qua đời; câu này thường nhắc người ta biết tận hưởng cuộc sống.","ex":"She bought tickets for a long-awaited trip, reminding herself that you can't take it with you.","exVi":"Cô mua vé cho chuyến đi mong đợi từ lâu, tự nhắc rằng tiền bạc không thể mang theo mãi.","src":null,"level":"general","topics":["Tiền bạc","Du lịch","Lối sống"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0288","text":"Old friends are best.","vi":"Những người bạn lâu năm thường đem lại sự thân thuộc và tin cậy đặc biệt.","ex":"After years apart, we picked up our conversation; old friends are best.","exVi":"Xa nhau nhiều năm, chúng tôi vẫn trò chuyện tự nhiên; bạn cũ vẫn thân thiết nhất.","src":null,"level":"general","topics":["Bạn bè","Mối quan hệ","Thời gian"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0289","text":"A rising tide lifts all boats.","vi":"Khi điều kiện chung được cải thiện, nhiều người hoặc nhóm trong cộng đồng đều có thể hưởng lợi.","ex":"Our community training program created jobs for many local families; a rising tide lifts all boats.","exVi":"Chương trình đào tạo tạo việc làm cho nhiều gia đình; khi cộng đồng đi lên, mọi người cùng hưởng lợi.","src":null,"level":"general","topics":["Cộng đồng","Công việc","Kinh tế"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0290","text":"After a storm comes a calm.","vi":"Sau biến cố, tình hình thường dần lắng dịu.","ex":"After weeks of disruption, the team found that after a storm comes a calm.","exVi":"Sau nhiều tuần xáo trộn, cả nhóm nhận ra rồi mọi chuyện cũng sẽ lắng dịu.","src":null,"level":"general","topics":["Thời tiết","Khó khăn"],"reg":"not-applicable","equiv":"Sau cơn mưa trời lại sáng","ielts":1,"reviewed":false},{"id":"prv-0291","text":"All is grist that comes to the mill.","vi":"Người khéo xoay xở có thể tận dụng nhiều loại cơ hội hoặc tình huống.","ex":"She turns every assignment into experience; all is grist that comes to the mill.","exVi":"Cô biến mỗi nhiệm vụ thành kinh nghiệm; việc gì cũng có thể tận dụng.","src":null,"level":"general","topics":["Công việc","Học tập"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0292","text":"All things are difficult before they are easy.","vi":"Việc mới thường khó lúc đầu, nhưng luyện tập khiến nó dần trở nên dễ hơn.","ex":"My first presentations felt awkward, but all things are difficult before they are easy.","exVi":"Những lần thuyết trình đầu khá vụng về, nhưng việc gì ban đầu cũng khó.","src":null,"level":"general","topics":["Học tập","Kiên trì"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0293","text":"As the twig is bent, so grows the tree.","vi":"Thói quen và cách giáo dục từ sớm có ảnh hưởng lâu dài đến sự trưởng thành.","ex":"The coach stressed daily practice; as the twig is bent, so grows the tree.","exVi":"Huấn luyện viên nhấn mạnh việc luyện tập hằng ngày vì nền nếp sớm ảnh hưởng lâu dài.","src":null,"level":"general","topics":["Giáo dục","Gia đình"],"reg":"not-applicable","equiv":"Uốn cây từ thuở còn non","ielts":0,"reviewed":false},{"id":"prv-0294","text":"Bad company corrupts good morals.","vi":"Bạn bè hoặc môi trường xấu có thể khiến một người dần thay đổi theo hướng tiêu cực.","ex":"Her parents worried that bad company corrupts good morals during those difficult years.","exVi":"Bố mẹ lo bạn xấu sẽ ảnh hưởng đến con trong những năm tháng khó khăn ấy.","src":null,"level":"general","topics":["Bạn bè","Đạo đức"],"reg":"not-applicable","equiv":"Gần mực thì đen","ielts":1,"reviewed":false},{"id":"prv-0295","text":"Better a live dog than a dead lion.","vi":"Còn sống trong hoàn cảnh khiêm tốn vẫn hơn có danh vọng nhưng không còn tồn tại.","ex":"He chose a modest life over a dangerous contest; better a live dog than a dead lion.","exVi":"Anh chọn cuộc sống bình dị thay vì cuộc tranh đấu nguy hiểm; sống vẫn hơn danh vọng đã mất.","src":null,"level":"general","topics":["Sức khỏe","Lối sống"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0296","text":"Better an open enemy than a false friend.","vi":"Người đối đầu công khai dễ đối phó hơn người giả vờ thân thiết nhưng âm thầm gây hại.","ex":"At least her rival was honest; better an open enemy than a false friend.","exVi":"Ít nhất đối thủ của cô còn thẳng thắn; kẻ thù công khai vẫn hơn bạn giả tạo.","src":null,"level":"general","topics":["Quan hệ","Giao tiếp"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0297","text":"Better to light a candle than curse the darkness.","vi":"Thay vì chỉ than phiền, hãy làm một việc nhỏ có ích để cải thiện tình hình.","ex":"Residents cleaned the park; better to light a candle than curse the darkness.","exVi":"Thay vì than phiền về công viên, cư dân cùng dọn dẹp; nên hành động thay vì chỉ trách móc.","src":null,"level":"general","topics":["Cộng đồng","Môi trường"],"reg":"not-applicable","equiv":"Một cây làm chẳng nên non","ielts":1,"reviewed":false},{"id":"prv-0298","text":"Beware of Greeks bearing gifts.","vi":"Hãy thận trọng với món quà hoặc đề nghị có thể che giấu ý đồ không tốt.","ex":"The offer seemed unusually generous, so I remembered: beware of Greeks bearing gifts.","exVi":"Lời đề nghị có vẻ quá hào phóng nên tôi nhớ rằng cần đề phòng quà tặng có dụng ý.","src":null,"level":"general","topics":["Tiền bạc","Ra quyết định"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0299","text":"A hungry stomach has no ears.","vi":"Người đang đói thường khó tập trung lắng nghe lời khuyên.","ex":"The children needed lunch before lessons; a hungry stomach has no ears.","exVi":"Bọn trẻ cần ăn trưa trước giờ học; khi đói bụng, người ta khó chú tâm nghe.","src":null,"level":"general","topics":["Đồ ăn","Giáo dục"],"reg":"not-applicable","equiv":"Có thực mới vực được đạo","ielts":1,"reviewed":false},{"id":"prv-0300","text":"One year’s seeding makes seven years’ weeding.","vi":"Một mùa gieo cỏ dại có thể khiến ta phải nhổ cỏ suốt nhiều năm sau.","ex":"He removed the weeds early; one year’s seeding makes seven years’ weeding.","exVi":"Anh nhổ cỏ sớm; để cỏ dại gieo hạt một năm có thể phải nhổ nhiều năm.","src":null,"level":"general","topics":["Môi trường","Làm vườn"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0301","text":"Every day is not Sunday.","vi":"Không phải ngày nào cũng thuận lợi hoặc vui vẻ; khó khăn là một phần bình thường của cuộc sống.","ex":"We had a tiring shift, but every day is not Sunday.","exVi":"Ca làm hôm nay khá mệt, nhưng đâu phải ngày nào cũng thuận buồm xuôi gió.","src":null,"level":"general","topics":["Công việc","Lối sống"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0302","text":"Every tide has its ebb.","vi":"Điều kiện và vận may luôn thay đổi; thời kỳ khó khăn rồi cũng có thể qua.","ex":"Sales fell this winter, but every tide has its ebb.","exVi":"Doanh số giảm vào mùa đông, nhưng vận thế nào rồi cũng đổi thay.","src":null,"level":"general","topics":["Kinh tế","Thời tiết"],"reg":"not-applicable","equiv":"Sông có khúc, người có lúc","ielts":1,"reviewed":false},{"id":"prv-0303","text":"Faint heart never won fair lady.","vi":"Muốn đạt được điều mình mong muốn, đôi khi cần can đảm chủ động.","ex":"He finally invited her to the dance, recalling that faint heart never won fair lady.","exVi":"Cuối cùng anh cũng mời cô đi khiêu vũ, tự nhắc rằng thiếu can đảm thì khó thành công.","src":null,"level":"general","topics":["Tình cảm","Can đảm"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0304","text":"Fair words butter no parsnips.","vi":"Lời nói hay không thay thế được hành động hoặc kết quả thực tế.","ex":"The manager promised changes, but fair words butter no parsnips; staff wanted a clear plan.","exVi":"Quản lý hứa sẽ thay đổi, nhưng lời hay không đủ; nhân viên cần kế hoạch cụ thể.","src":null,"level":"general","topics":["Công việc","Giao tiếp"],"reg":"not-applicable","equiv":"Nói dễ hơn làm","ielts":1,"reviewed":false},{"id":"prv-0305","text":"First catch your hare.","vi":"Hãy chắc chắn có đủ điều kiện cần thiết trước khi bàn cách hoàn thành việc gì.","ex":"Before planning the feast, first catch your hare and confirm the budget.","exVi":"Trước khi lên thực đơn tiệc, hãy xác nhận ngân sách và nguồn nguyên liệu trước.","src":null,"level":"general","topics":["Lập kế hoạch","Đồ ăn"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0306","text":"Give a dog a bad name and hang him.","vi":"Một khi đã mang tiếng xấu, người ta dễ bị quy lỗi dù chưa có đủ bằng chứng.","ex":"After one mistake, colleagues blamed her for every delay; give a dog a bad name and hang him.","exVi":"Sau một sai lầm, đồng nghiệp đổ mọi lần chậm trễ cho cô; tiếng xấu khiến người ta dễ bị quy kết.","src":null,"level":"general","topics":["Công việc","Danh tiếng"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0307","text":"Good fences make good neighbours.","vi":"Ranh giới và thỏa thuận rõ ràng giúp những người sống gần nhau giữ quan hệ tốt.","ex":"They agreed on quiet hours; good fences make good neighbours.","exVi":"Họ thống nhất giờ yên tĩnh; ranh giới rõ ràng giúp hàng xóm hòa thuận.","src":null,"level":"general","topics":["Nhà cửa","Quan hệ"],"reg":"not-applicable","equiv":"Đất có lề, quê có thói","ielts":1,"reviewed":false},{"id":"prv-0308","text":"Handsome is as handsome does.","vi":"Phẩm chất và hành động mới cho thấy một người có tốt đẹp hay không.","ex":"She treats everyone kindly; handsome is as handsome does.","exVi":"Cô đối xử tử tế với mọi người; vẻ đẹp thật nằm ở cách cư xử.","src":null,"level":"general","topics":["Tính cách","Quan hệ"],"reg":"not-applicable","equiv":"Tốt gỗ hơn tốt nước sơn","ielts":1,"reviewed":false},{"id":"prv-0309","text":"He that goes a-borrowing goes a-sorrowing.","vi":"Vay mượn quá nhiều có thể dẫn đến áp lực và rắc rối tài chính.","ex":"He borrowed for every purchase and learned that he that goes a-borrowing goes a-sorrowing.","exVi":"Anh vay tiền cho mọi món đồ rồi nhận ra vay mượn liên tục dễ chuốc phiền muộn.","src":null,"level":"general","topics":["Tiền bạc","Lối sống"],"reg":"not-applicable","equiv":"Vay thì trả","ielts":0,"reviewed":false},{"id":"prv-0310","text":"He who knows nothing doubts nothing.","vi":"Người thiếu hiểu biết đôi khi quá tự tin vì không nhận ra điều mình chưa biết.","ex":"The novice dismissed every warning; he who knows nothing doubts nothing.","exVi":"Người mới gạt bỏ mọi lời cảnh báo; thiếu hiểu biết đôi khi khiến ta quá chắc chắn.","src":null,"level":"general","topics":["Học tập","Tư duy"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0311","text":"Keep your powder dry.","vi":"Hãy chuẩn bị sẵn sàng để có thể hành động khi cơ hội hoặc thử thách xuất hiện.","ex":"The team saved its budget for urgent repairs, keeping its powder dry.","exVi":"Nhóm giữ lại ngân sách cho việc sửa chữa khẩn cấp để luôn sẵn sàng ứng phó.","src":null,"level":"general","topics":["Lập kế hoạch","Công việc"],"reg":"not-applicable","equiv":"Phòng khi nước đến chân","ielts":0,"reviewed":false},{"id":"prv-0312","text":"Marry in haste, repent at leisure.","vi":"Quyết định vội vàng, nhất là chuyện trọng đại, có thể dẫn đến hối tiếc lâu dài.","ex":"They took time to discuss their plans, mindful that marry in haste, repent at leisure.","exVi":"Họ dành thời gian bàn bạc vì quyết định vội vàng có thể dẫn đến hối tiếc lâu dài.","src":null,"level":"general","topics":["Tình cảm","Ra quyết định"],"reg":"not-applicable","equiv":"Cưới vợ phải cưới liền tay","ielts":0,"reviewed":false},{"id":"prv-0313","text":"Misfortunes never come singly.","vi":"Rắc rối đôi khi xuất hiện liên tiếp thay vì chỉ xảy ra riêng lẻ.","ex":"The bus broke down after her phone died; misfortunes never come singly.","exVi":"Xe buýt hỏng sau khi điện thoại hết pin; rắc rối đôi khi kéo đến liên tiếp.","src":null,"level":"general","topics":["Sự kiện","Khó khăn"],"reg":"not-applicable","equiv":"Họa vô đơn chí","ielts":1,"reviewed":false},{"id":"prv-0314","text":"Never too old to learn.","vi":"Ở bất kỳ độ tuổi nào, con người vẫn có thể học thêm điều mới.","ex":"My grandfather started using a tablet at seventy; never too old to learn.","exVi":"Ông tôi bắt đầu dùng máy tính bảng ở tuổi bảy mươi; học hỏi không bao giờ là muộn.","src":null,"level":"general","topics":["Học tập","Tuổi tác"],"reg":"not-applicable","equiv":"Học, học nữa, học mãi","ielts":1,"reviewed":false},{"id":"prv-0315","text":"The devil is not so black as he is painted.","vi":"Một người hoặc tình huống có thể không tệ như lời đồn hoặc ấn tượng ban đầu.","ex":"The new supervisor listened carefully; the devil is not so black as he is painted.","exVi":"Người quản lý mới lắng nghe rất kỹ; ông ấy không tệ như lời đồn.","src":null,"level":"general","topics":["Công việc","Định kiến"],"reg":"not-applicable","equiv":"Trăm nghe không bằng một thấy","ielts":1,"reviewed":false},{"id":"prv-0316","text":"The fish rots from the head.","vi":"Một tổ chức thường suy yếu khi người lãnh đạo thiếu trách nhiệm hoặc năng lực.","ex":"Staff morale collapsed under dishonest leadership; the fish rots from the head.","exVi":"Tinh thần nhân viên sa sút dưới sự lãnh đạo thiếu trung thực; vấn đề bắt đầu từ cấp trên.","src":null,"level":"general","topics":["Công việc","Lãnh đạo"],"reg":"not-applicable","equiv":"Thượng bất chính, hạ tắc loạn","ielts":0,"reviewed":false},{"id":"prv-0317","text":"The pitcher goes to the well once too often.","vi":"Lặp lại một hành động rủi ro quá nhiều lần cuối cùng có thể dẫn đến hậu quả.","ex":"He kept ignoring safety rules; the pitcher goes to the well once too often.","exVi":"Anh liên tục phớt lờ quy tắc an toàn; hành động liều lĩnh lặp lại rồi sẽ gặp hậu quả.","src":null,"level":"general","topics":["An toàn","Thói quen"],"reg":"not-applicable","equiv":"Đi đêm lắm có ngày gặp ma","ielts":0,"reviewed":false},{"id":"prv-0318","text":"The pot boils best on its own fire.","vi":"Người ta thường cảm thấy dễ chịu nhất trong không gian và nếp sống quen thuộc của mình.","ex":"After months abroad, she missed home cooking; the pot boils best on its own fire.","exVi":"Sau nhiều tháng ở nước ngoài, cô nhớ món nhà nấu; ở nhà vẫn thấy thoải mái nhất.","src":null,"level":"general","topics":["Nhà cửa","Đồ ăn"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0319","text":"The way to a man's heart is through his stomach.","vi":"Nấu món ngon là một cách thân thiện để bày tỏ sự quan tâm và tạo thiện cảm.","ex":"He cooked her favourite soup, joking that the way to a man's heart is through his stomach.","exVi":"Anh nấu món súp cô thích, đùa rằng đồ ăn ngon dễ khiến người ta xiêu lòng.","src":null,"level":"general","topics":["Đồ ăn","Quan hệ"],"reg":"not-applicable","equiv":"Con đường ngắn nhất đến trái tim là qua dạ dày","ielts":0,"reviewed":false},{"id":"prv-0320","text":"There's many a good tune played on an old fiddle.","vi":"Tuổi tác không ngăn cản một người tiếp tục hữu ích, tài năng hoặc tận hưởng cuộc sống.","ex":"At eighty, she still performed beautifully; there's many a good tune played on an old fiddle.","exVi":"Ở tuổi tám mươi, bà vẫn biểu diễn tuyệt hay; tuổi tác không ngăn tài năng tỏa sáng.","src":null,"level":"general","topics":["Tuổi tác","Nghệ thuật"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0321","text":"There's no fool like an old fool.","vi":"Một người lớn tuổi vẫn có thể hành động thiếu suy nghĩ, đặc biệt trong chuyện tình cảm.","ex":"He ignored sensible advice for a risky romance; there's no fool like an old fool.","exVi":"Ông bỏ ngoài tai lời khuyên vì chuyện tình cảm bốc đồng; tuổi cao không đồng nghĩa luôn sáng suốt.","src":null,"level":"general","topics":["Tuổi tác","Tình cảm"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0322","text":"There's safety in numbers.","vi":"Ở trong một nhóm đôi khi giúp mọi người cảm thấy an toàn và hỗ trợ lẫn nhau.","ex":"The hikers stayed together after sunset; there's safety in numbers.","exVi":"Những người đi bộ đường dài ở cạnh nhau sau hoàng hôn; đi theo nhóm giúp an toàn hơn.","src":null,"level":"general","topics":["Du lịch","An toàn"],"reg":"not-applicable","equiv":"Đi đông cho vui","ielts":1,"reviewed":false},{"id":"prv-0323","text":"Those who live by the sword shall die by the sword.","vi":"Dùng bạo lực có thể khiến một người cuối cùng phải chịu chính bạo lực ấy.","ex":"The novel warns that those who live by the sword shall die by the sword.","exVi":"Cuốn tiểu thuyết cảnh báo rằng người dùng bạo lực có thể phải chịu hậu quả tương tự.","src":null,"level":"general","topics":["Xung đột","Đạo đức"],"reg":"not-applicable","equiv":"Gieo gió gặt bão","ielts":0,"reviewed":false},{"id":"prv-0324","text":"A kind word is never wasted.","vi":"Lời tử tế luôn có thể đem lại sự an ủi hoặc khích lệ cho ai đó.","ex":"She thanked the cleaner; a kind word is never wasted.","exVi":"Cô cảm ơn người lao công; một lời tử tế luôn có ý nghĩa.","src":null,"level":"general","topics":["Giao tiếp","Quan hệ"],"reg":"not-applicable","equiv":"Lời nói chẳng mất tiền mua","ielts":1,"reviewed":false},{"id":"prv-0325","text":"You never miss the water till the well runs dry.","vi":"Người ta thường chỉ nhận ra giá trị của thứ quen thuộc sau khi mất đi nó.","ex":"After the old library closed, we learned you never miss the water till the well runs dry.","exVi":"Sau khi thư viện cũ đóng cửa, chúng tôi mới biết quý điều mình từng có.","src":null,"level":"general","topics":["Cộng đồng","Giá trị"],"reg":"not-applicable","equiv":"Mất bò mới lo làm chuồng","ielts":1,"reviewed":false},{"id":"prv-0326","text":"A good conscience is a soft pillow.","vi":"Sống ngay thẳng giúp con người thanh thản và dễ ngủ ngon hơn.","ex":"She admitted the mistake and slept peacefully; a good conscience is a soft pillow.","exVi":"Cô nhận lỗi rồi ngủ ngon; sống ngay thẳng giúp lòng thanh thản.","src":null,"level":"general","topics":["Đạo đức","Sức khỏe"],"reg":"not-applicable","equiv":"Cây ngay không sợ chết đứng","ielts":0,"reviewed":false},{"id":"prv-0327","text":"Never spend your money before you have it.","vi":"Đừng tiêu trước khoản thu nhập chưa chắc chắn; hãy chi tiêu trong khả năng.","ex":"He waited for payday before booking the trip; never spend your money before you have it.","exVi":"Anh chờ đến ngày nhận lương mới đặt chuyến đi; đừng tiêu trước tiền chưa có.","src":null,"level":"general","topics":["Tiền bạc","Du lịch"],"reg":"not-applicable","equiv":"Liệu cơm gắp mắm","ielts":1,"reviewed":false},{"id":"prv-0328","text":"One may as well be hanged for a sheep as a lamb.","vi":"Khi đã bị buộc tội nghiêm trọng, người ta có thể nghĩ không còn gì để mất.","ex":"He joked that one may as well be hanged for a sheep as a lamb.","exVi":"Dù kết quả phạt như nhau, anh đùa rằng đã thế thì làm lớn luôn cũng vậy.","src":null,"level":"general","topics":["Ra quyết định","Rủi ro"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0329","text":"The higher the monkey climbs, the more he shows his tail.","vi":"Càng cố phô trương địa vị, một người càng dễ để lộ khuyết điểm.","ex":"He bragged about every promotion; the higher the monkey climbs, the more he shows his tail.","exVi":"Anh khoe khoang mọi lần thăng chức; càng phô trương càng dễ lộ thiếu sót.","src":null,"level":"general","topics":["Công việc","Tính cách"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0330","text":"A volunteer is worth twenty pressed men.","vi":"Người tự nguyện thường làm việc với tinh thần chủ động hơn người bị ép buộc.","ex":"The neighbours volunteered to rebuild the playground; a volunteer is worth twenty pressed men.","exVi":"Hàng xóm tự nguyện sửa sân chơi; người làm bằng lòng nhiệt tình thường rất đáng quý.","src":null,"level":"general","topics":["Cộng đồng","Công việc"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0331","text":"Ask a silly question and you'll get a silly answer.","vi":"Câu hỏi thiếu suy nghĩ thường nhận lại câu trả lời đùa cợt hoặc không hữu ích.","ex":"He asked whether fish need water; ask a silly question and you'll get a silly answer.","exVi":"Anh hỏi cá có cần nước không; hỏi điều ngớ ngẩn thì dễ nhận câu trả lời ngớ ngẩn.","src":null,"level":"general","topics":["Giao tiếp","Học tập"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0332","text":"A promise is a debt.","vi":"Đã hứa thì cần thực hiện lời hứa như một nghĩa vụ của mình.","ex":"He kept his word and returned the book; a promise is a debt.","exVi":"Anh giữ lời và trả lại cuốn sách; đã hứa thì phải thực hiện.","src":null,"level":"general","topics":["Đạo đức","Quan hệ"],"reg":"not-applicable","equiv":"Nói lời phải giữ lấy lời","ielts":1,"reviewed":false},{"id":"prv-0333","text":"Bad money drives out good.","vi":"Khi tiền kém chất lượng lưu thông cùng tiền tốt, người ta thường giữ tiền tốt lại.","ex":"Collectors kept the older coins at home; bad money drives out good.","exVi":"Người sưu tầm giữ đồng tiền tốt ở nhà; tiền kém chất lượng có thể đẩy tiền tốt khỏi lưu thông.","src":null,"level":"general","topics":["Tiền bạc","Kinh tế"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0334","text":"Between two stools one falls to the ground.","vi":"Do dự giữa hai lựa chọn hoặc cố giữ cả hai có thể khiến ta mất cả hai.","ex":"She delayed choosing either course and lost both places; between two stools one falls to the ground.","exVi":"Cô chần chừ giữa hai khóa học rồi mất cả hai chỗ; cố giữ hai lựa chọn có thể khiến ta trắng tay.","src":null,"level":"general","topics":["Ra quyết định","Học tập"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0335","text":"Big fish eat little fish.","vi":"Trong môi trường cạnh tranh, tổ chức lớn thường có lợi thế trước tổ chức nhỏ.","ex":"Small shops struggled after the chain arrived; big fish eat little fish.","exVi":"Các cửa hàng nhỏ gặp khó khi chuỗi lớn xuất hiện; doanh nghiệp lớn thường lấn át doanh nghiệp nhỏ.","src":null,"level":"general","topics":["Kinh doanh","Cạnh tranh"],"reg":"not-applicable","equiv":"Cá lớn nuốt cá bé","ielts":1,"reviewed":false},{"id":"prv-0336","text":"Bread always falls buttered side down.","vi":"Những chuyện không may dường như hay xảy ra vào lúc ta ít mong đợi nhất.","ex":"My toast landed on the clean floor; bread always falls buttered side down.","exVi":"Miếng bánh mì rơi xuống sàn vừa lau; chuyện xui thường xảy ra đúng lúc không mong.","src":null,"level":"general","topics":["Đồ ăn","Sự kiện"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0337","text":"Cold hands, warm heart.","vi":"Người có vẻ ngoài lạnh lùng hoặc ít nói vẫn có thể rất tốt bụng.","ex":"He rarely speaks, but he always helps neighbours; cold hands, warm heart.","exVi":"Anh ít nói nhưng luôn giúp hàng xóm; vẻ ngoài lạnh lùng không có nghĩa là thiếu tình cảm.","src":null,"level":"general","topics":["Tính cách","Quan hệ"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0338","text":"Count your blessings.","vi":"Hãy trân trọng những điều tốt đẹp mình đang có thay vì chỉ tập trung vào thiếu sót.","ex":"After a difficult week, she listed what went well and reminded herself to count her blessings.","exVi":"Sau tuần khó khăn, cô kể ra những điều tốt đẹp và tự nhắc phải biết trân trọng chúng.","src":null,"level":"general","topics":["Cảm xúc","Lối sống"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0339","text":"Do as I say, not as I do.","vi":"Lời nói khuyên bảo của ai đó có thể khác với cách chính họ hành động.","ex":"He admitted his own bad habits: do as I say, not as I do.","exVi":"Anh thừa nhận thói quen xấu của mình: hãy nghe lời tôi nói, đừng bắt chước tôi làm.","src":null,"level":"general","topics":["Gia đình","Giao tiếp"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0340","text":"Don't keep a dog and bark yourself.","vi":"Đừng thuê hoặc giao việc cho người khác rồi tự mình làm thay phần của họ.","ex":"The manager hired an assistant but did every task; don't keep a dog and bark yourself.","exVi":"Quản lý thuê trợ lý nhưng tự làm mọi việc; đã giao việc thì nên để người khác đảm nhận.","src":null,"level":"general","topics":["Công việc","Quản lý"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0341","text":"Don't shut the stable door after the horse has bolted.","vi":"Phòng ngừa sau khi sự việc đã xảy ra thường là quá muộn.","ex":"They installed alarms after the theft; don't shut the stable door after the horse has bolted.","exVi":"Họ lắp báo động sau vụ trộm; ngăn ngừa sau khi sự việc xảy ra thì đã muộn.","src":null,"level":"general","topics":["An toàn","Ra quyết định"],"reg":"not-applicable","equiv":"Mất bò mới lo làm chuồng","ielts":1,"reviewed":false},{"id":"prv-0342","text":"Tomorrow never comes.","vi":"Nếu cứ trì hoãn hành động, thời điểm thích hợp có thể không bao giờ đến.","ex":"She began the application today because tomorrow never comes.","exVi":"Cô bắt đầu nộp hồ sơ hôm nay vì cứ chờ ngày mai thì sẽ mãi trì hoãn.","src":null,"level":"general","topics":["Thời gian","Ra quyết định"],"reg":"not-applicable","equiv":"Việc hôm nay chớ để ngày mai","ielts":1,"reviewed":false},{"id":"prv-0343","text":"Give a man a fish and you feed him for a day.","vi":"Giúp đỡ trực tiếp giải quyết nhu cầu trước mắt, nhưng dạy kỹ năng có thể tạo ích lợi lâu dài.","ex":"She taught him to budget; give a man a fish and you feed him for a day.","exVi":"Cô dạy hàng xóm cách lập ngân sách, vì giúp họ có kỹ năng sẽ ích lợi lâu dài.","src":null,"level":"general","topics":["Giáo dục","Tiền bạc"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0344","text":"Give a man enough rope and he will hang himself.","vi":"Nếu để người thiếu thận trọng tự do hành động, họ có thể tự bộc lộ sai lầm.","ex":"The auditor waited for the full records; give a man enough rope and he will hang himself.","exVi":"Kiểm toán viên chờ đủ hồ sơ; cứ để người ta hành động, sai sót có thể tự lộ ra.","src":null,"level":"general","topics":["Công việc","Đạo đức"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0345","text":"Hard cases make bad law.","vi":"Quy định tạo ra chỉ để giải quyết một trường hợp đặc biệt có thể gây hệ quả không tốt về lâu dài.","ex":"The judge warned that hard cases make bad law when rules are changed for one unusual dispute.","exVi":"Thẩm phán cảnh báo rằng sửa luật vì một vụ việc lạ có thể tạo tiền lệ không tốt.","src":null,"level":"general","topics":["Pháp luật","Ra quyết định"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0346","text":"Hard work never did anyone any harm.","vi":"Nỗ lực nghiêm túc thường có ích, miễn là không bỏ qua sức khỏe và thời gian nghỉ ngơi.","ex":"She practised daily but rested on Sundays; hard work never did anyone any harm.","exVi":"Cô luyện tập mỗi ngày nhưng nghỉ Chủ nhật; làm việc chăm chỉ có ích khi biết nghỉ hợp lý.","src":null,"level":"general","topics":["Công việc","Sức khỏe"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0347","text":"He who fights and runs away may live to fight another day.","vi":"Rút lui đúng lúc đôi khi giúp ta bảo toàn sức lực để thử lại sau.","ex":"He retreated; he who fights and runs away may live to fight another day.","exVi":"Nhóm đi bộ quay lại trước cơn bão; rút lui đúng lúc giúp họ có cơ hội thử lại.","src":null,"level":"general","topics":["Du lịch","An toàn"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0348","text":"He who sups with the devil should have a long spoon.","vi":"Khi giao du với người nguy hiểm hoặc không đáng tin, cần giữ khoảng cách và đề phòng.","ex":"The journalist checked every claim carefully; he who sups with the devil should have a long spoon.","exVi":"Nhà báo kiểm tra kỹ từng lời khai; làm việc với người nguy hiểm thì cần hết sức thận trọng.","src":null,"level":"general","topics":["Giao tiếp","An toàn"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0349","text":"If anything can go wrong, it will.","vi":"Câu nói đùa rằng khi có khả năng xảy ra trục trặc, ta nên chuẩn bị phương án dự phòng.","ex":"We packed spare batteries because if anything can go wrong, it will.","exVi":"Chúng tôi mang pin dự phòng vì mọi thứ có thể trục trặc vào lúc bất tiện nhất.","src":null,"level":"general","topics":["Công nghệ","Lập kế hoạch"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0350","text":"If a job is worth doing, it is worth doing well.","vi":"Nếu một việc đáng để bắt đầu, hãy cố gắng thực hiện cẩn thận và có trách nhiệm.","ex":"She reviewed the report twice; if a job is worth doing, it is worth doing well.","exVi":"Cô xem lại báo cáo hai lần; việc gì đáng làm thì nên làm cho đàng hoàng.","src":null,"level":"general","topics":["Công việc","Học tập"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0351","text":"If you pay peanuts, you get monkeys.","vi":"Trả công quá thấp thường khó thu hút người có kỹ năng hoặc dịch vụ tốt.","ex":"The firm raised its offer after delays; if you pay peanuts, you get monkeys.","exVi":"Công ty tăng mức đãi ngộ sau nhiều lần chậm trễ; trả quá thấp thì khó thuê người giỏi.","src":null,"level":"general","topics":["Công việc","Tiền bạc"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0352","text":"Never speak ill of the dead.","vi":"Nên tránh nói xấu người đã qua đời, đặc biệt khi họ không còn cơ hội tự giải thích.","ex":"At the memorial, they chose to remember his generosity; never speak ill of the dead.","exVi":"Trong lễ tưởng niệm, họ chọn nhớ đến lòng tốt của ông; đừng nói xấu người đã khuất.","src":null,"level":"general","topics":["Gia đình","Giao tiếp"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0353","text":"Nine tailors make a man.","vi":"Một số việc cần nhiều người cùng góp sức mới hoàn thành được.","ex":"The costume took a whole team to finish; nine tailors make a man.","exVi":"Cả đội cùng hoàn thành bộ trang phục; có những việc cần nhiều người chung tay.","src":null,"level":"general","topics":["Công việc","Cộng đồng"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0354","text":"Oil and water don't mix.","vi":"Một số người, ý tưởng hoặc vật chất không dễ hòa hợp với nhau.","ex":"Their working styles clashed from the start; oil and water don't mix.","exVi":"Phong cách làm việc của họ xung khắc từ đầu; có những thứ khó hòa hợp.","src":null,"level":"general","topics":["Quan hệ","Công việc"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0355","text":"One hand washes the other.","vi":"Sự giúp đỡ qua lại có thể đem lại lợi ích cho cả hai bên.","ex":"They exchanged language lessons; one hand washes the other.","exVi":"Họ đổi buổi dạy ngôn ngữ cho nhau; sự hỗ trợ qua lại đem lợi ích cho cả đôi bên.","src":null,"level":"general","topics":["Quan hệ","Học tập"],"reg":"not-applicable","equiv":"Có đi có lại","ielts":1,"reviewed":false},{"id":"prv-0356","text":"Possession is nine points of the law.","vi":"Người đang nắm giữ tài sản thường có lợi thế khi quyền sở hữu bị tranh chấp.","ex":"The proverb says possession is nine points of the law, though ownership documents still matter.","exVi":"Tục ngữ nói người đang nắm giữ có lợi thế, nhưng giấy tờ sở hữu vẫn rất quan trọng.","src":null,"level":"general","topics":["Pháp luật","Tài sản"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0357","text":"Rob Peter to pay Paul.","vi":"Dùng tiền hoặc nguồn lực lấy từ khoản này để bù cho khoản khác mà không giải quyết gốc rễ.","ex":"Moving rent money to cover a loan only robbed Peter to pay Paul.","exVi":"Lấy tiền thuê nhà trả khoản vay chỉ là chuyển khó khăn từ chỗ này sang chỗ khác.","src":null,"level":"general","topics":["Tiền bạc","Lập kế hoạch"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0358","text":"See no evil, hear no evil, speak no evil.","vi":"Câu nói khuyên không nhìn, nghe hoặc nói điều xấu; đôi khi phê phán thái độ làm ngơ.","ex":"They ignored the signs: see no evil, hear no evil, speak no evil.","exVi":"Hàng xóm phớt lờ dấu hiệu cảnh báo; họ chọn cách không nhìn, không nghe và không nói.","src":null,"level":"general","topics":["Đạo đức","Cộng đồng"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0359","text":"You are what you eat.","vi":"Thức ăn ảnh hưởng đáng kể đến sức khỏe và cảm giác thể chất của con người.","ex":"He added vegetables to lunch, remembering that you are what you eat.","exVi":"Anh thêm rau vào bữa trưa, nhớ rằng ăn uống ảnh hưởng trực tiếp đến sức khỏe.","src":null,"level":"general","topics":["Đồ ăn","Sức khỏe"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0360","text":"You can choose your friends, but you can't choose your family.","vi":"Ta có thể tự chọn bạn bè, nhưng quan hệ gia đình thường không do ta lựa chọn.","ex":"They disagree often, yet you can choose your friends, but you can't choose your family.","exVi":"Họ thường bất đồng, nhưng bạn bè thì chọn được còn gia đình thì không.","src":null,"level":"general","topics":["Gia đình","Quan hệ"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0361","text":"A golden key can open any door.","vi":"Tiền bạc hoặc nguồn lực phù hợp có thể giúp giải quyết nhiều trở ngại thực tế.","ex":"The grant covered her tuition; a golden key can open any door.","exVi":"Khoản tài trợ giúp cô đóng học phí; nguồn lực phù hợp có thể mở ra nhiều cơ hội.","src":null,"level":"general","topics":["Tiền bạc","Giáo dục"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0362","text":"A dog is a man's best friend.","vi":"Chó thường được yêu quý vì sự trung thành và tình cảm dành cho con người.","ex":"Her dog waited by the gate every evening; a dog is a man's best friend.","exVi":"Chú chó đợi cô bên cổng mỗi tối; chó thường là người bạn trung thành của con người.","src":null,"level":"general","topics":["Động vật","Gia đình"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0363","text":"A prophet is not recognized in his own land.","vi":"Tài năng của một người đôi khi được người ngoài đánh giá cao hơn cộng đồng quê nhà.","ex":"Her research gained attention abroad first; a prophet is not recognized in his own land.","exVi":"Nghiên cứu của cô được chú ý ở nước ngoài trước; người tài đôi khi chưa được quê nhà công nhận.","src":null,"level":"general","topics":["Công việc","Danh tiếng"],"reg":"not-applicable","equiv":"Bụt chùa nhà không thiêng","ielts":0,"reviewed":false},{"id":"prv-0364","text":"A house is not a home.","vi":"Một căn nhà chỉ thực sự trở thành tổ ấm khi có sự gắn bó và tình cảm.","ex":"They filled the new flat with family photos; a house is not a home without warmth.","exVi":"Họ treo ảnh gia đình trong căn hộ mới; mái nhà cần sự ấm áp mới thành tổ ấm.","src":null,"level":"general","topics":["Nhà cửa","Gia đình"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0365","text":"An army marches on its stomach.","vi":"Đủ thức ăn và hậu cần là điều thiết yếu để một đội ngũ duy trì hoạt động hiệu quả.","ex":"The expedition planned meals before routes; an army marches on its stomach.","exVi":"Đoàn thám hiểm lên thực đơn trước khi chọn đường; hậu cần đầy đủ rất quan trọng.","src":null,"level":"general","topics":["Đồ ăn","Lập kế hoạch"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0366","text":"Any port in a storm.","vi":"Khi gặp khó khăn, một lựa chọn đủ an toàn có thể tốt hơn việc chờ lựa chọn hoàn hảo.","ex":"With every hotel booked, the travellers accepted a hostel; any port in a storm.","exVi":"Khi khách sạn đều kín chỗ, họ nhận phòng ở nhà trọ; lúc khó khăn có chỗ trú là quý.","src":null,"level":"general","topics":["Du lịch","Khó khăn"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0367","text":"There is no rose without a thorn.","vi":"Niềm vui hoặc điều tốt đẹp thường đi kèm một số khó khăn và đánh đổi.","ex":"The promotion brought extra duties; there is no rose without a thorn.","exVi":"Được thăng chức cũng đi kèm thêm trách nhiệm; điều tốt đẹp thường có đánh đổi.","src":null,"level":"general","topics":["Công việc","Thành công"],"reg":"not-applicable","equiv":"Không có hoa hồng nào không có gai","ielts":1,"reviewed":false},{"id":"prv-0368","text":"Christmas comes but once a year.","vi":"Dịp lễ đặc biệt chỉ đến ít lần, nên mọi người thường sẵn lòng chi tiêu hoặc ăn mừng.","ex":"They bought a small cake for the family; Christmas comes but once a year.","exVi":"Họ mua chiếc bánh nhỏ cho cả nhà; dịp lễ đặc biệt chỉ đến mỗi năm một lần.","src":null,"level":"general","topics":["Gia đình","Lễ hội"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0369","text":"Don't mix business with pleasure.","vi":"Nên tách biệt công việc và vui chơi để tránh ảnh hưởng đến trách nhiệm hoặc quan hệ.","ex":"They kept the holiday conversation light; don't mix business with pleasure.","exVi":"Họ tránh bàn công việc trong kỳ nghỉ; nên tách biệt công việc với vui chơi.","src":null,"level":"general","topics":["Công việc","Lối sống"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0370","text":"A good beginning makes a good ending.","vi":"Khởi đầu tốt thường tạo nền tảng thuận lợi để hoàn thành công việc.","ex":"We planned carefully from day one; a good beginning makes a good ending.","exVi":"Chúng tôi lên kế hoạch cẩn thận từ ngày đầu; khởi đầu tốt giúp kết quả thuận lợi.","src":null,"level":"general","topics":["Lập kế hoạch","Công việc"],"reg":"not-applicable","equiv":"Đầu xuôi đuôi lọt","ielts":1,"reviewed":false},{"id":"prv-0371","text":"A nod is as good as a wink to a blind horse.","vi":"Một lời gợi ý ngắn cũng đủ cho người đã hiểu ý.","ex":"She understood his hint immediately; a nod is as good as a wink to a blind horse.","exVi":"Cô hiểu ngay lời gợi ý của anh; người hiểu ý thì không cần giải thích dài.","src":null,"level":"general","topics":["Giao tiếp","Quan hệ"],"reg":"not-applicable","equiv":"Người khôn nói ít hiểu nhiều","ielts":1,"reviewed":false},{"id":"prv-0372","text":"A young idler, an old beggar.","vi":"Lười biếng khi còn trẻ có thể khiến tuổi già thiếu thốn.","ex":"He saved and learned a trade; a young idler, an old beggar.","exVi":"Anh vừa tiết kiệm vừa học nghề; lười biếng lúc trẻ có thể khiến tuổi già khó khăn.","src":null,"level":"general","topics":["Công việc","Tuổi tác"],"reg":"not-applicable","equiv":"Trẻ cậy cha, già cậy con","ielts":0,"reviewed":false},{"id":"prv-0373","text":"An old fox is not easily snared.","vi":"Người nhiều kinh nghiệm thường khó bị đánh lừa.","ex":"The veteran negotiator noticed the hidden fee; an old fox is not easily snared.","exVi":"Nhà đàm phán dày dạn nhận ra khoản phí ẩn; người nhiều kinh nghiệm khó bị mắc lừa.","src":null,"level":"general","topics":["Kinh nghiệm","Tiền bạc"],"reg":"not-applicable","equiv":"Gừng càng già càng cay","ielts":1,"reviewed":false},{"id":"prv-0374","text":"Ask no questions and hear no lies.","vi":"Đôi khi không hỏi về điều nhạy cảm giúp tránh nghe lời nói dối hoặc gây khó xử.","ex":"He avoided probing into her private matter; ask no questions and hear no lies.","exVi":"Anh không hỏi sâu chuyện riêng của cô; đôi khi không hỏi giúp tránh nghe lời nói dối.","src":null,"level":"general","topics":["Giao tiếp","Quan hệ"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0375","text":"Better a little fire to warm us than a great one to burn us.","vi":"Điều vừa đủ và an toàn đôi khi tốt hơn tham vọng quá mức gây hại.","ex":"We chose wisely; better a little fire to warm us than a great one to burn us.","exVi":"Khoản vay nhỏ nằm trong khả năng; vừa đủ an toàn tốt hơn tham vọng quá mức.","src":null,"level":"general","topics":["Tiền bạc","An toàn"],"reg":"not-applicable","equiv":"Tham thì thâm","ielts":0,"reviewed":false},{"id":"prv-0376","text":"Better be the head of a dog than the tail of a lion.","vi":"Đôi khi làm người dẫn đầu trong một nhóm nhỏ thích hợp hơn chỉ là cấp dưới trong nhóm lớn.","ex":"She led the small team; better be the head of a dog than the tail of a lion.","exVi":"Cô chọn dẫn dắt đội địa phương; làm người đứng đầu nhóm nhỏ đôi khi phù hợp hơn.","src":null,"level":"general","topics":["Công việc","Lãnh đạo"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0377","text":"Do not halloo till you are out of the wood.","vi":"Đừng ăn mừng hoặc tuyên bố thành công trước khi thực sự vượt qua khó khăn.","ex":"The team waited for final approval; do not halloo till you are out of the wood.","exVi":"Nhóm chờ phê duyệt cuối cùng; đừng vội ăn mừng khi việc chưa thật sự xong.","src":null,"level":"general","topics":["Công việc","Kiên trì"],"reg":"not-applicable","equiv":"Chớ thấy sóng cả mà ngã tay chèo","ielts":1,"reviewed":false},{"id":"prv-0378","text":"Do not kick against the pricks.","vi":"Đừng cố chống lại điều không thể thay đổi theo cách chỉ khiến bản thân chịu thiệt.","ex":"He accepted the new timetable instead of arguing; do not kick against the pricks.","exVi":"Anh chấp nhận thời khóa biểu mới thay vì tranh cãi; chống lại điều không đổi được chỉ thêm thiệt thân.","src":null,"level":"general","topics":["Ra quyết định","Học tập"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0379","text":"Do not make fish of one and flesh of another.","vi":"Hãy đối xử công bằng, đừng ưu ái người này và khắt khe với người khác.","ex":"The teacher used one marking standard for everyone; do not make fish of one and flesh of another.","exVi":"Giáo viên chấm mọi người theo cùng một tiêu chuẩn; đừng thiên vị người này hơn người kia.","src":null,"level":"general","topics":["Giáo dục","Công bằng"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0380","text":"Do not spur a willing horse.","vi":"Đừng thúc ép quá mức người vốn đã sẵn lòng và chủ động làm việc.","ex":"Her coach quoted, do not spur a willing horse, because she practised daily.","exVi":"Cô vốn đã luyện tập mỗi ngày nên huấn luyện viên không thúc ép thêm.","src":null,"level":"general","topics":["Công việc","Học tập"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0381","text":"Every man is the architect of his own fortune.","vi":"Lựa chọn và hành động của mỗi người góp phần tạo nên tương lai của họ.","ex":"He built his career through steady effort; every man is the architect of his own fortune.","exVi":"Anh xây dựng sự nghiệp bằng nỗ lực bền bỉ; mỗi người góp phần tạo nên tương lai mình.","src":null,"level":"general","topics":["Công việc","Thành công"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0382","text":"Fools build houses, wise men live in them.","vi":"Người có tầm nhìn có thể hưởng lợi từ công sức hoặc sai lầm của người khác.","ex":"The investor bought the abandoned property cheaply; fools build houses, wise men live in them.","exVi":"Nhà đầu tư mua rẻ căn nhà bỏ trống; người sáng suốt đôi khi biết tận dụng công sức có sẵn.","src":null,"level":"general","topics":["Nhà cửa","Tiền bạc"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0383","text":"He that is warm thinks all so.","vi":"Người đang có điều kiện thuận lợi đôi khi quên rằng người khác có thể đang thiếu thốn.","ex":"The manager assumed every worker had heating at home; he that is warm thinks all so.","exVi":"Quản lý cho rằng ai cũng có máy sưởi ở nhà; người đủ đầy đôi khi quên khó khăn của người khác.","src":null,"level":"general","topics":["Cộng đồng","Đời sống"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0384","text":"He who would climb the ladder must begin at the bottom.","vi":"Muốn tiến xa, ta thường phải bắt đầu từ những bước cơ bản.","ex":"She started as an intern; he who would climb the ladder must begin at the bottom.","exVi":"Cô bắt đầu với vị trí thực tập; muốn tiến xa thường phải khởi đầu từ việc cơ bản.","src":null,"level":"general","topics":["Công việc","Kiên trì"],"reg":"not-applicable","equiv":"Có công mài sắt, có ngày nên kim","ielts":1,"reviewed":false},{"id":"prv-0385","text":"If you can't be good, be careful.","vi":"Nếu không thể cư xử đúng mực, ít nhất hãy thận trọng để tránh gây thêm rắc rối.","ex":"He joked before sending the message: if you can't be good, be careful.","exVi":"Anh đùa trước khi gửi tin nhắn: nếu không định ngoan thì ít nhất hãy cẩn thận.","src":null,"level":"general","topics":["Giao tiếp","Đạo đức"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0386","text":"It's an ill bird that fouls its own nest.","vi":"Người làm hại chính cộng đồng hoặc gia đình mình thường bị đánh giá rất tiêu cực.","ex":"She refused to spread damaging rumours; it's an ill bird that fouls its own nest.","exVi":"Cô không lan truyền tin đồn gây hại; làm tổn thương chính cộng đồng mình là điều đáng chê trách.","src":null,"level":"general","topics":["Cộng đồng","Gia đình"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0387","text":"The first hundred years are the hardest.","vi":"Câu nói hài hước rằng một công việc kéo dài mãi hoặc rất gian nan.","ex":"After another renovation delay, he joked that the first hundred years are the hardest.","exVi":"Sau lần trì hoãn sửa nhà nữa, anh đùa rằng trăm năm đầu tiên là khó nhất.","src":null,"level":"general","topics":["Nhà cửa","Hài hước"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0388","text":"A secret between more than two is no secret.","vi":"Bí mật càng được chia sẻ với nhiều người thì càng khó giữ kín.","ex":"She told only one trusted friend; a secret between more than two is no secret.","exVi":"Cô chỉ kể với một người bạn đáng tin; bí mật càng nhiều người biết càng khó giữ.","src":null,"level":"general","topics":["Quan hệ","Bí mật"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0389","text":"Ne'er cast a clout till May be out.","vi":"Tục ngữ thời tiết khuyên chưa nên cất áo ấm cho đến khi tháng Năm kết thúc.","ex":"The mornings stayed chilly, so my grandmother quoted, ne'er cast a clout till May be out.","exVi":"Sáng vẫn lạnh nên bà tôi nhắc chưa hết tháng Năm thì đừng cất áo ấm.","src":null,"level":"general","topics":["Thời tiết","Gia đình"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0390","text":"Red sky at night, shepherd's delight.","vi":"Bầu trời đỏ lúc hoàng hôn thường được xem là dấu hiệu thời tiết thuận lợi ngày hôm sau.","ex":"The sunset glowed red; red sky at night, shepherd's delight.","exVi":"Hoàng hôn đỏ rực; trời đỏ buổi tối thường báo hiệu ngày mai thuận lợi.","src":null,"level":"general","topics":["Thời tiết","Thiên nhiên"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0391","text":"March comes in like a lion and goes out like a lamb.","vi":"Thời tiết tháng Ba thường bắt đầu khắc nghiệt rồi dịu dần về cuối tháng.","ex":"March was harsh; March comes in like a lion and goes out like a lamb.","exVi":"Gió lạnh dịu đi vào cuối tháng Ba; đầu tháng khắc nghiệt rồi cuối tháng dễ chịu hơn.","src":null,"level":"general","topics":["Thời tiết","Thiên nhiên"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0392","text":"Never go to bed on an argument.","vi":"Cố gắng giải quyết bất đồng trước khi nghỉ ngơi để tránh kéo dài căng thẳng.","ex":"They apologized before sleeping; never go to bed on an argument.","exVi":"Họ xin lỗi nhau trước khi ngủ; đừng để bất đồng kéo dài qua đêm.","src":null,"level":"general","topics":["Quan hệ","Gia đình"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0393","text":"A good name is sooner lost than won.","vi":"Danh tiếng tốt khó gây dựng nhưng có thể mất đi rất nhanh.","ex":"She guarded her reputation; a good name is sooner lost than won.","exVi":"Cô giữ gìn danh tiếng; danh tiếng tốt khó gây dựng nhưng dễ mất đi.","src":null,"level":"general","topics":["Danh tiếng","Quan hệ"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0394","text":"Don't spoil the ship for a ha'p'orth of tar.","vi":"Đừng vì tiết kiệm một khoản nhỏ mà làm hỏng một việc hoặc tài sản lớn.","ex":"They bought proper sealant; don't spoil the ship for a ha'p'orth of tar.","exVi":"Họ mua keo chống thấm tốt; đừng vì tiếc khoản nhỏ mà làm hỏng việc lớn.","src":null,"level":"general","topics":["Tiền bạc","Nhà cửa"],"reg":"not-applicable","equiv":"Tham bát bỏ mâm","ielts":0,"reviewed":false},{"id":"prv-0395","text":"First impressions are the most lasting.","vi":"Ấn tượng đầu tiên thường ảnh hưởng lâu dài đến cách ta nhìn nhận một người.","ex":"He arrived prepared and polite; first impressions are the most lasting.","exVi":"Anh đến đúng giờ và lịch sự; ấn tượng đầu tiên thường khó phai.","src":null,"level":"general","topics":["Quan hệ","Công việc"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0396","text":"Finders keepers, losers weepers.","vi":"Câu nói trẻ con cho rằng người tìm được món đồ có thể giữ nó, dù không phải quy tắc sở hữu thực tế.","ex":"The children laughed, chanting finders keepers, losers weepers over a toy.","exVi":"Bọn trẻ cười và đọc câu ai tìm được thì giữ khi tranh nhau món đồ chơi.","src":null,"level":"general","topics":["Trẻ em","Đồ vật"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false},{"id":"prv-0397","text":"Even a worm will turn.","vi":"Người thường nhẫn nhịn cũng có lúc phản kháng nếu bị đối xử tệ quá lâu.","ex":"After months of unfair treatment, she finally protested; even a worm will turn.","exVi":"Sau nhiều tháng bị đối xử bất công, cuối cùng cô lên tiếng; ai cũng có giới hạn.","src":null,"level":"general","topics":["Công bằng","Cảm xúc"],"reg":"not-applicable","equiv":"Tức nước vỡ bờ","ielts":1,"reviewed":false},{"id":"prv-0398","text":"Flattery will get you nowhere.","vi":"Nịnh nọt không giúp đạt kết quả thực chất hoặc xây dựng sự tin tưởng lâu dài.","ex":"The committee wanted evidence, not compliments; flattery will get you nowhere.","exVi":"Hội đồng cần bằng chứng chứ không cần lời tâng bốc; nịnh nọt không ích gì.","src":null,"level":"general","topics":["Công việc","Giao tiếp"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0399","text":"Horses for courses.","vi":"Người hoặc phương pháp khác nhau phù hợp với những hoàn cảnh và nhiệm vụ khác nhau.","ex":"One tutor suited beginners, another advanced learners; horses for courses.","exVi":"Một gia sư hợp với người mới, người khác hợp với học viên nâng cao; mỗi người một thế mạnh.","src":null,"level":"general","topics":["Giáo dục","Công việc"],"reg":"not-applicable","equiv":"","ielts":1,"reviewed":false},{"id":"prv-0400","text":"You pays your money and you takes your choice.","vi":"Sau khi biết các lựa chọn và đánh đổi, mỗi người tự quyết định theo sở thích của mình.","ex":"Both routes had drawbacks; you pays your money and you takes your choice.","exVi":"Cả hai tuyến đường đều có bất tiện; cuối cùng mỗi người tự chọn điều mình thích.","src":null,"level":"general","topics":["Ra quyết định","Du lịch"],"reg":"not-applicable","equiv":"","ielts":0,"reviewed":false}]};
